def fail(message):
    raise ValueError(message)


def pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            fail('duplicate JSON key: ' + key)
        result[key] = value
    return result


def load(path):
    limit = 2 * 1024 * 1024
    fd = os.open(path, os.O_RDONLY | os.O_NONBLOCK)
    with os.fdopen(fd, encoding='utf-8') as f:
        info = os.fstat(f.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_size > limit:
            fail('JSON input must be a regular file no larger than 2 MiB')
        text = f.read(limit + 1)
        if len(text) > limit:
            fail('JSON input exceeds 2 MiB')
        return json.loads(text, object_pairs_hook=pairs,
                          parse_constant=lambda _: fail('non-finite JSON number'))


def emit(value):
    print(json.dumps(value, ensure_ascii=False, indent=2))


def port(value):
    if not isinstance(value, str) or not re.fullmatch(r'[0-9]{1,5}', value):
        fail('port must be a decimal string of 1-5 digits')
    if not 1 <= int(value) <= 65535:
        fail('port outside 1-65535')
    return str(int(value))


def domain(value):
    if not isinstance(value, str) or len(value) > 253:
        fail('invalid hostname')
    if not re.fullmatch(r'(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?', value):
        fail('use an ASCII fully qualified hostname (punycode for Unicode)')
    return value.lower()


def host(value):
    try:
        if '%' in value:
            fail('scoped addresses are unsupported')
        return str(ipaddress.ip_address(value))
    except ValueError:
        if re.fullmatch(r'[0-9.]+', value):
            fail('invalid IPv4 address')
        return domain(value)


def endpoint(value):
    if not isinstance(value, str):
        fail('endpoint must be a string')
    match = re.fullmatch(r'\[([0-9a-fA-F:]+)\]:([0-9]{1,5})', value)
    if match:
        address = ipaddress.IPv6Address(match[1])
        return f'[{address}]:{port(match[2])}'
    match = re.fullmatch(r'([^:\[\]]+):([0-9]{1,5})', value)
    if not match:
        fail('endpoint requires hostname:port, IPv4:port or [IPv6]:port')
    return host(match[1]) + ':' + port(match[2])


def name(value):
    if not isinstance(value, str) or not 1 <= len(value.encode('utf-8')) <= 100:
        fail('client name must contain 1-100 UTF-8 bytes')
    if any(ord(c) < 32 or ord(c) == 127 for c in value):
        fail('control characters are forbidden in names')
    return value


def sid(value):
    if not isinstance(value, str) or not re.fullmatch(r'(?:[0-9a-fA-F]{2}){1,8}', value):
        fail('shortId must contain 2-16 hexadecimal digits, in pairs')
    return value.lower()


def profile(value):
    if not isinstance(value, dict):
        fail('profile must be a JSON object')
    allowed = set(DEFAULTS) | {'profile_format', 'generated_at_utc', 'script_version'}
    if set(value) - allowed:
        fail('unknown profile field: ' + ', '.join(sorted(set(value) - allowed)))
    if value.get('profile_format', '2') not in ('1', '2'):
        fail('unsupported profile_format')
    for k, v in value.items():
        if not isinstance(v, str) or '\x00' in v:
            fail('profile fields must be strings: ' + k)
    result = dict(DEFAULTS)
    result.update({k: v for k, v in value.items() if k in DEFAULTS})
    for k in ('LISTEN_PORT', 'SSH_PORT', 'CAMOUFLAGE_WEB_PORT'):
        result[k] = port(result[k])
    if result['FALLBACK_PORT']:
        result['FALLBACK_PORT'] = port(result['FALLBACK_PORT'])
    result['SERVER_NAME'] = domain(result['SERVER_NAME'])
    result['DEST_ENDPOINT'] = endpoint(result['DEST_ENDPOINT'])
    for k in DEFAULTS:
        if DEFAULTS[k] in ('yes', 'no') and result[k] not in ('yes', 'no'):
            fail(k + ' must be yes or no')
    enums = {'FIREWALL_STYLE': ('none', 'nftables', 'ufw'),
             'XRAY_UPDATE_POLICY': ('manual', 'weekly', 'daily'),
             'LOG_PROFILE': ('minimal', 'verbose')}
    for k, choices in enums.items():
        if result[k] not in choices:
            fail('unsupported ' + k)
    if result['OS_PRIVATE_OUTBOUND'] == 'yes' and result['FIREWALL_STYLE'] != 'nftables':
        fail('OS_PRIVATE_OUTBOUND requires nftables')
    try:
        result['LISTEN_ADDRESS'] = str(ipaddress.ip_address(result['LISTEN_ADDRESS']))
    except ValueError:
        fail('LISTEN_ADDRESS must be an IPv4 or IPv6 literal')
    if not re.fullmatch(r'[0-9]{1,2}', result['SHORT_ID_COUNT']) or not 1 <= int(result['SHORT_ID_COUNT']) <= 16:
        fail('SHORT_ID_COUNT must be 1-16')
    result['SHORT_ID_COUNT'] = str(int(result['SHORT_ID_COUNT']))
    for key, minimum, maximum in [('XRAY_HANDSHAKE_TIMEOUT_SEC', 1, 60),
                                  ('XRAY_CONN_IDLE_TIMEOUT_SEC', 1, 86400),
                                  ('XRAY_UPLINK_ONLY_TIMEOUT_SEC', 0, 3600),
                                  ('XRAY_DOWNLINK_ONLY_TIMEOUT_SEC', 0, 3600)]:
        if not re.fullmatch(r'[0-9]{1,5}', result[key]) or not minimum <= int(result[key]) <= maximum:
            fail('invalid timeout range: ' + key)
        result[key] = str(int(result[key]))
    resolvers = result['DNS_SERVERS'].split(',')
    if not 1 <= len(resolvers) <= 8:
        fail('DNS_SERVERS requires 1-8 comma-separated resolver IPs')
    try:
        result['DNS_SERVERS'] = ','.join(str(ipaddress.ip_address(r)) for r in resolvers)
    except ValueError:
        fail('DNS_SERVERS requires IPv4 or IPv6 literals')
    name(result['PROFILE_NAME'])
    name(result['SHORT_ID_LABEL'])
    if result['PUBLIC_IP']:
        result['PUBLIC_IP'] = host(result['PUBLIC_IP'])
    if result['XRAY_PIN'] and not re.fullmatch(r'v[0-9]{1,3}\.[0-9]{1,2}\.[0-9]{1,2}', result['XRAY_PIN']):
        fail('XRAY_PIN requires a release tag such as v26.3.27')
    ports = [result['LISTEN_PORT']]
    if result['FALLBACK_PORT']:
        ports.append(result['FALLBACK_PORT'])
    if result['CAMOUFLAGE_ENABLED'] == 'yes':
        ports.append(result['CAMOUFLAGE_WEB_PORT'])
    if len(set(ports)) != len(ports) or result['SSH_PORT'] in ports:
        fail('Xray, SSH and local web ports must be different')
    result['profile_format'] = '2'
    return result


def identity(value):
    if not isinstance(value, dict) or set(value) != {'private_key', 'public_key'}:
        fail('invalid identity fields')
    for k in value:
        if not isinstance(value[k], str) or not re.fullmatch(r'[A-Za-z0-9_-]{43}', value[k]):
            fail('invalid X25519 key encoding')
        if len(base64.urlsafe_b64decode(value[k] + '=')) != 32:
            fail('invalid X25519 key length')
    return value


def state(value):
    expected = {'format', 'options', 'identity', 'clients', 'short_ids', 'rotation', 'xray_version'}
    if not isinstance(value, dict) or set(value) != expected or type(value['format']) is not int or value['format'] != 2:
        fail('unsupported state format or fields')
    value['options'] = profile(value['options'])
    identity(value['identity'])
    if not isinstance(value['clients'], list) or not 1 <= len(value['clients']) <= 1024:
        fail('deployment must contain 1-1024 clients')
    names, ids = set(), set()
    for c in value['clients']:
        if not isinstance(c, dict) or set(c) != {'name', 'id', 'short_id'}:
            fail('invalid client fields')
        name(c['name'])
        if not isinstance(c['id'], str) or not re.fullmatch(r'[0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}', c['id']):
            fail('client UUID must be canonical')
        c['id'] = str(uuid.UUID(c['id']))
        c['short_id'] = sid(c['short_id'])
        if c['name'] in names or c['id'] in ids:
            fail('duplicate client name or UUID')
        names.add(c['name'])
        ids.add(c['id'])
    if not isinstance(value['short_ids'], list) or not 1 <= len(value['short_ids']) <= 4096:
        fail('invalid short_ids list')
    value['short_ids'] = list(dict.fromkeys(sid(s) for s in value['short_ids']))
    if any(c['short_id'] not in value['short_ids'] for c in value['clients']):
        fail('client shortId is not accepted by the server')
    r = value['rotation']
    if r is not None:
        if not isinstance(r, dict) or set(r) != {'old_ids', 'finalize_after'} or type(r['finalize_after']) is not int or r['finalize_after'] < 0:
            fail('invalid rotation metadata')
        if not isinstance(r['old_ids'], list) or not r['old_ids']:
            fail('invalid old shortIds')
        for s in r['old_ids']:
            if sid(s) not in value['short_ids'] or s in [c['short_id'] for c in value['clients']]:
                fail('invalid rotation mapping')
    if not isinstance(value['xray_version'], str) or not re.fullmatch(r'v[0-9]{1,3}\.[0-9]{1,2}\.[0-9]{1,2}', value['xray_version']):
        fail('invalid deployment Xray version')
    return value


def legacy_word(word):
    # Decode Bash printf %q as data, including octal UTF-8 under LC_ALL=C.
    # No shell, substitutions, or eval are involved.
    if not (word.startswith("$'") and word.endswith("'")):
        if re.search(r'(?<!\\)[;$`|&<>\n()]', word):
            fail('legacy state contains shell operators')
        words = shlex.split(word)
        if len(words) != 1:
            fail('legacy state must contain one literal word per value')
        return words[0]
    body, result, index = word[2:-1], bytearray(), 0
    escapes = {'a': '\a', 'b': '\b', 'e': '\x1b', 'E': '\x1b',
               'f': '\f', 'n': '\n', 'r': '\r', 't': '\t', 'v': '\v',
               '\\': '\\', "'": "'", '"': '"', '?': '?'}
    while index < len(body):
        c = body[index]
        index += 1
        if c == "'":
            fail('invalid legacy quoting')
        if c != '\\':
            result.extend(c.encode('utf-8'))
            continue
        if index == len(body):
            fail('incomplete legacy escape')
        c = body[index]
        index += 1
        if c in escapes:
            result.extend(escapes[c].encode())
        elif c in '01234567':
            digits = re.match(r'[0-7]{0,2}', body[index:])[0]
            index += len(digits)
            result.append(int(c + digits, 8) % 256)
        elif c in 'xuU':
            maximum = {'x': 2, 'u': 4, 'U': 8}[c]
            digits = re.match(r'[0-9a-fA-F]{1,' + str(maximum) + '}', body[index:])
            if not digits:
                fail('invalid legacy numeric escape')
            index += len(digits[0])
            value = int(digits[0], 16)
            if c == 'x':
                result.append(value)
            elif value > 0x10ffff or 0xd800 <= value <= 0xdfff:
                fail('invalid legacy Unicode escape')
            else:
                result.extend(chr(value).encode('utf-8'))
        else:
            fail('unsupported legacy escape')
    return result.decode('utf-8')


def legacy(path, config_path):
    values = {}
    allowed = set(DEFAULTS) | {'SCRIPT_VERSION', 'OS_ID', 'OS_VERSION_ID', 'XRAY_ASSET',
              'XRAY_VERSION', 'UUID', 'REALITY_PRIVATE_KEY', 'REALITY_PUBLIC_KEY',
              'REALITY_SHORT_ID', 'REALITY_SHORT_IDS', 'HTTP_CONNECT_TIMEOUT',
              'HTTP_MAX_TIME', 'HTTP_RETRIES', 'HTTP_RETRY_DELAY',
              'XRAY_HANDSHAKE_TIMEOUT_SEC', 'XRAY_CONN_IDLE_TIMEOUT_SEC',
              'XRAY_UPLINK_ONLY_TIMEOUT_SEC', 'XRAY_DOWNLINK_ONLY_TIMEOUT_SEC'}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\n')
            if not line or line.startswith('#'):
                continue
            match = re.fullmatch(r'([A-Z][A-Z0-9_]*)=(.*)', line)
            if not match or match[1] not in allowed or match[1] in values:
                fail('legacy state contains unsupported syntax or fields')
            values[match[1]] = legacy_word(match[2])
    cfg = load(config_path)
    inbounds = cfg.get('inbounds', [])
    vless = [i for i in inbounds if i.get('protocol') == 'vless']
    if not vless:
        fail('no VLESS inbound for migration')
    if len(inbounds) != len(vless) or any(i.get('tag') not in ('vless-reality-primary', 'vless-reality-fallback') for i in inbounds):
        fail('legacy config contains unmanaged inbounds; migrate manually to preserve them')
    if len({i['tag'] for i in vless}) != len(vless) or not any(i['tag'] == 'vless-reality-primary' for i in vless):
        fail('legacy config requires one primary and at most one alternate listener')
    vless.sort(key=lambda i: i['tag'] != 'vless-reality-primary')
    if any([(c['id'], c.get('flow', '')) for c in i['settings']['clients']] != [(c['id'], c.get('flow', '')) for c in vless[0]['settings']['clients']] for i in vless):
        fail('legacy listeners contain different clients; migrate manually to preserve them')
    reality = vless[0]['streamSettings']['realitySettings']
    clients = vless[0]['settings']['clients']
    ids = list(dict.fromkeys(sid(s) for s in reality['shortIds']))
    deployed = []
    for inbound in vless:
        stream = inbound['streamSettings']
        transport = stream['realitySettings']
        if (stream.get('network') not in ('tcp', 'raw') or stream.get('security') != 'reality'
                or transport.get('xver', 0) != 0 or len(transport['serverNames']) != 1
                or any(c.get('flow') != 'xtls-rprx-vision' for c in inbound['settings']['clients'])):
            fail('custom legacy transport settings require manual migration')
        target = endpoint(transport.get('target', transport.get('dest')))
        if 'target' in transport and 'dest' in transport and endpoint(transport['dest']) != target:
            fail('conflicting legacy REALITY target aliases')
        deployed.append({'LISTEN_PORT': port(str(inbound['port'])),
            'LISTEN_ADDRESS': str(ipaddress.ip_address(inbound.get('listen', '0.0.0.0'))),
            'SERVER_NAME': domain(transport['serverNames'][0]), 'DEST_ENDPOINT': target})
        if (transport['privateKey'] != reality['privateKey']
                or {sid(s) for s in transport['shortIds']} != set(ids)):
            fail('legacy listeners have different REALITY credentials; migrate manually')
    for other in deployed[1:]:
        if any(other[k] != deployed[0][k] for k in ('LISTEN_ADDRESS', 'SERVER_NAME', 'DEST_ENDPOINT')):
            fail('legacy listeners have different network settings; migrate manually')
    if values.get('REALITY_PRIVATE_KEY') != reality['privateKey']:
        fail('legacy state/config key mismatch; restore a consistent backup first')
    if values.get('UUID') != clients[0]['id']:
        fail('legacy state/config UUID mismatch')
    opts = profile({k: v for k, v in values.items() if k in DEFAULTS})
    network = {**deployed[0], 'FALLBACK_PORT': deployed[1]['LISTEN_PORT'] if len(deployed) == 2 else ''}
    for key, actual in network.items():
        if key in values and opts[key] != actual:
            fail('legacy state/config network mismatch: ' + key + '; reconcile before migration')
        opts[key] = actual
    # Upgrading software must never silently reapply old host-wide defaults.
    opts.update(FIREWALL_STYLE='none', SSH_HARDENING='no', FAIL2BAN_ENABLED='no',
                UNATTENDED_UPGRADES_ENABLED='no', CAMOUFLAGE_ENABLED='no')
    migrated = []
    for index, c in enumerate(clients):
        migrated.append({'name': opts['PROFILE_NAME'] if index == 0 else 'legacy-' + str(index),
                         'id': c['id'], 'short_id': ids[0]})
    return state({'format': 2, 'options': opts, 'identity': {
        'private_key': reality['privateKey'], 'public_key': values['REALITY_PUBLIC_KEY']},
        'clients': migrated, 'short_ids': ids, 'rotation': None,
        'xray_version': values['XRAY_VERSION']})


def config(s):
    o = s['options']
    inbounds = []
    for tag, p in [('primary', o['LISTEN_PORT']), ('alternate', o['FALLBACK_PORT'])]:
        if not p:
            continue
        inbounds.append({'tag': 'vless-reality-' + tag, 'listen': o['LISTEN_ADDRESS'],
            'port': int(p), 'protocol': 'vless', 'settings': {'decryption': 'none',
            'clients': [{'id': c['id'], 'flow': 'xtls-rprx-vision',
                         'email': hashlib.sha256(c['name'].encode()).hexdigest()[:24] + '@xray'}
                        for c in s['clients']]}, 'streamSettings': {
            'network': 'raw', 'security': 'reality', 'realitySettings': {
            'show': False, 'target': o['DEST_ENDPOINT'], 'xver': 0,
            'serverNames': [o['SERVER_NAME']], 'privateKey': s['identity']['private_key'],
            'shortIds': s['short_ids']}}, 'sniffing': {'enabled': False}})
    block = o['BLOCK_PRIVATE_OUTBOUND'] == 'yes'
    # Xray normalizes mapped addresses to IPv4 and rejects the mapped /96 CIDR.
    ranges = V4 + [cidr for cidr in V6 if cidr != '::ffff:0:0/96']
    # Recent Freedom versions enforce finalRules on the resolved/dialed address.
    # An explicit opt-out must override their built-in private-IP default.
    final_rules = [{'action': 'block', 'ip': ranges}] if block else [
        {'action': 'allow', 'ip': ['0.0.0.0/0', '::/0']}]

    return {'log': {'access': 'none' if o['LOG_PROFILE'] == 'minimal' else '/var/log/xray/access.log',
                   'error': '/var/log/xray/error.log', 'loglevel': 'warning' if o['LOG_PROFILE'] == 'minimal' else 'info'},
            'policy': {'levels': {'0': {'handshake': int(o['XRAY_HANDSHAKE_TIMEOUT_SEC']),
                'connIdle': int(o['XRAY_CONN_IDLE_TIMEOUT_SEC']),
                'uplinkOnly': int(o['XRAY_UPLINK_ONLY_TIMEOUT_SEC']),
                'downlinkOnly': int(o['XRAY_DOWNLINK_ONLY_TIMEOUT_SEC'])}}},
            'dns': {'servers': o['DNS_SERVERS'].split(','), 'queryStrategy': 'UseIP'},
            'inbounds': inbounds,
            'outbounds': [{'tag': 'direct', 'protocol': 'freedom', 'settings': {'finalRules': final_rules},
                'streamSettings': {'sockopt': {'domainStrategy': 'UseIP', 'happyEyeballs': {
                    'prioritizeIPv6': False, 'interleave': 1, 'tryDelayMs': 250, 'maxConcurrentTry': 2}}}}]
                         + ([{'tag': 'blocked', 'protocol': 'blackhole'}] if block else []),
            'routing': {'domainStrategy': 'IPOnDemand' if block else 'AsIs',
                        'rules': [{'type': 'field', 'ip': ranges, 'outboundTag': 'blocked'}] if block else []}}


def find_client(s, client_name):
    for c in s['clients']:
        if c['name'] == client_name:
            return c
    fail('client name does not exist')


def mutate(s, operation, client_name, window):
    if operation == 'add-client':
        name(client_name)
        if any(c['name'] == client_name for c in s['clients']):
            fail('client name already exists')
        new_sid = secrets.token_hex(8)
        s['short_ids'].append(new_sid)
        s['clients'].append({'name': client_name, 'id': str(uuid.uuid4()), 'short_id': new_sid})
    elif operation in ('remove-client', 'rotate-client'):
        c = find_client(s, client_name)
        if operation == 'remove-client':
            if len(s['clients']) == 1:
                fail('cannot remove the last client')
            s['clients'].remove(c)
            retained = {client['short_id'] for client in s['clients']}
            if s['rotation']:
                retained.update(s['rotation']['old_ids'])
            if c['short_id'] not in retained:
                s['short_ids'].remove(c['short_id'])
        else:
            c['id'] = str(uuid.uuid4())
        # ShortIds are global REALITY gates, not tied cryptographically to UUIDs.
    elif operation == 'rotate-shortid':
        if s['rotation'] is not None:
            fail('finalize the existing shortId rotation first')
        old = s['short_ids'][:]
        for c in s['clients']:
            c['short_id'] = secrets.token_hex(8)
            s['short_ids'].append(c['short_id'])
        s['rotation'] = {'old_ids': old, 'finalize_after': int(datetime.datetime.now().timestamp()) + window}
    elif operation == 'finalize-shortid':
        if not s['rotation']:
            fail('no pending shortId rotation')
        if int(datetime.datetime.now().timestamp()) < s['rotation']['finalize_after']:
            fail('migration window has not elapsed')
        s['short_ids'] = [c['short_id'] for c in s['clients']]
        s['rotation'] = None
    return state(s)


def export(s, client_name, directory):
    c = find_client(s, client_name)
    o = s['options']
    address = o['PUBLIC_IP']
    if not address:
        fail('set PUBLIC_IP to the server public IP or hostname before exporting')
    authority = '[' + address + ']' if ':' in address else address
    prefix = hashlib.sha256(client_name.encode()).hexdigest()[:24]
    os.makedirs(directory, mode=0o700, exist_ok=True)
    def write(suffix, content):
        path = os.path.join(directory, prefix + suffix)
        flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW
        fd = os.open(path, flags, 0o600)
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            f.write(content)
        return path
    for label, p in [('primary', o['LISTEN_PORT']), ('fallback', o['FALLBACK_PORT'])]:
        if not p:
            continue
        uri = f"vless://{c['id']}@{authority}:{p}?encryption=none&flow=xtls-rprx-vision&security=reality&sni={quote(o['SERVER_NAME'], safe='')}&fp=chrome&pbk={quote(s['identity']['public_key'], safe='')}&sid={c['short_id']}&type=tcp&spx=%2F#{quote(client_name, safe='')}"
        write('-' + label + '.uri.txt', uri + '\n')
        client = {'log': {'loglevel': 'warning'}, 'outbounds': [{'tag': 'proxy', 'protocol': 'vless',
            'settings': {'vnext': [{'address': address, 'port': int(p), 'users': [{'id': c['id'],
                                  'encryption': 'none', 'flow': 'xtls-rprx-vision'}]}]},
            'streamSettings': {'network': 'raw', 'security': 'reality', 'realitySettings': {
            'serverName': o['SERVER_NAME'], 'fingerprint': 'chrome',
            'password': s['identity']['public_key'], 'shortId': c['short_id'], 'spiderX': '/'}}}]}
        for flavor in ('v2rayn', 'v2rayng'):
            write('-' + flavor + '-' + label + '.json', json.dumps(client, ensure_ascii=False, indent=2) + '\n')
        sing = {'type': 'vless', 'tag': client_name, 'server': address, 'server_port': int(p),
                'uuid': c['id'], 'flow': 'xtls-rprx-vision', 'packet_encoding': 'xudp',
                'tls': {'enabled': True, 'server_name': o['SERVER_NAME'],
                        'utls': {'enabled': True, 'fingerprint': 'chrome'},
                        'reality': {'enabled': True, 'public_key': s['identity']['public_key'], 'short_id': c['short_id']}}}
        write('-sing-box-' + label + '.json', json.dumps(sing, ensure_ascii=False, indent=2) + '\n')
    print(prefix)


def extract(archive, directory):
    with zipfile.ZipFile(archive) as z:
        total = 0
        for item in z.infolist():
            if item.filename.startswith('/') or '..' in item.filename.split('/') or '\\' in item.filename or (item.external_attr >> 16) & 0o170000 == 0o120000:
                fail('unsafe release archive member')
            total += item.file_size
            if total > 512 * 1024 * 1024:
                fail('release archive exceeds unpacked size limit')
        z.testzip() is None or fail('corrupt release archive')
        z.extractall(directory)


def egress_check(options_path, resolver_path):
    o = profile(load(options_path))
    if o['OS_PRIVATE_OUTBOUND'] != 'yes':
        return
    ranges = [ipaddress.ip_network(c) for c in V4 + V6]
    def blocked(address):
        return any(address.version == r.version and address in r for r in ranges)
    for resolver in o['DNS_SERVERS'].split(','):
        if blocked(ipaddress.ip_address(resolver)):
            fail('OS egress policy blocks a configured DNS resolver; use reachable public resolver IPs')
    target = o['DEST_ENDPOINT'].rsplit(':', 1)[0].strip('[]')
    try:
        address = ipaddress.ip_address(target)
    except ValueError:
        with open(resolver_path, encoding='utf-8') as f:
            servers = [line.split()[1] for line in f if line.startswith('nameserver ') and len(line.split()) >= 2]
        if not servers or all(blocked(ipaddress.ip_address(r)) for r in servers):
            fail('OS egress blocks the system DNS used by the REALITY hostname; configure a public system resolver or a public literal target IP')
    else:
        if blocked(address):
            fail('OS egress policy blocks the REALITY target; select a reachable public TLS endpoint')


def main():
    if len(sys.argv) < 2:
        fail('data command required')
    command, a = sys.argv[1], sys.argv[2:]
    counts = {'defaults':0, 'profile':1, 'profile-legacy':3, 'profile-deployed':2, 'state':1, 'migrate':2, 'config':1,
              'mutate':4, 'export':3, 'extract':2, 'validate':2, 'cidrs':1,
              'egress-check':2, 'key-der':2, 'public-key':1}
    if command not in counts or len(a) != counts[command]:
        fail('invalid data command or argument count')
    if command == 'defaults':
        emit(profile({}))
    elif command == 'profile':
        emit(profile(load(a[0])))
    elif command in ('profile-legacy', 'profile-deployed'):
        raw = load(a[0])
        if not isinstance(raw, dict):
            fail('profile must be a JSON object')
        deployed = legacy(a[1], a[2]) if command == 'profile-legacy' else state(load(a[1]))
        raw.setdefault('LISTEN_ADDRESS', deployed['options']['LISTEN_ADDRESS'])
        emit(profile(raw))
    elif command == 'state':
        emit(state(load(a[0])))
    elif command == 'migrate':
        emit(legacy(a[0], a[1]))
    elif command == 'config':
        emit(config(state(load(a[0]))))
    elif command == 'mutate':
        emit(mutate(state(load(a[0])), a[1], a[2], int(a[3])))
    elif command == 'export':
        export(state(load(a[0])), a[1], a[2])
    elif command == 'extract':
        extract(a[0], a[1])
    elif command == 'validate':
        {'port': port, 'endpoint': endpoint, 'domain': domain, 'host': host,
         'shortid': sid, 'name': name}[a[0]](a[1])
    elif command == 'key-der':
        value = state(load(a[0]))
        raw = base64.urlsafe_b64decode(value['identity']['private_key'] + '=')
        fd = os.open(a[1], os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW, 0o600)
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, 'wb') as f:
            f.write(bytes.fromhex('302e020100300506032b656e04220420') + raw)
    elif command == 'public-key':
        with open(a[0], 'rb') as f:
            der = f.read()
        if len(der) != 44 or not der.startswith(bytes.fromhex('302a300506032b656e032100')):
            fail('invalid X25519 public key DER')
        print(base64.urlsafe_b64encode(der[-32:]).decode().rstrip('='))
    elif command == 'egress-check':
        egress_check(a[0], a[1])
    elif command == 'cidrs':
        emit(V4 if a[0] == '4' else V6)
    else:
        fail('unknown data operation')


if __name__ == '__main__':
    try:
        main()
    except (ValueError, KeyError, TypeError, IndexError, OSError, zipfile.BadZipFile) as e:
        # Do not print values from state/configuration in error messages.
        message = str(e) if isinstance(e, ValueError) else type(e).__name__
        print('Data validation failed: ' + json.dumps(message, ensure_ascii=True), file=sys.stderr)
        sys.exit(2)

XRAY_BOOTSTRAP_PYTHON
}
#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
init_paths() {
  MODE=install
  OPLOG=''
  XRAY_DIR=/etc/xray
  CURRENT=$XRAY_DIR/current
  DEPLOYMENTS=$XRAY_DIR/deployments
  STATE_FILE=$CURRENT/state.json
  CONFIG_FILE=$CURRENT/config.json
  BIN=/usr/local/bin/xray
  UNIT=/etc/systemd/system/xray.service
  HELPER=/usr/local/sbin/xray-reality-bootstrap
  BACKUPS=/var/backups/xray-bootstrap
  JOURNAL=/var/lib/xray-bootstrap
  CLIENT_DIR=/root/xray-client-configs
  SSH_DROPIN=/etc/ssh/sshd_config.d/00-xray-bootstrap.conf
  NFT_FILE=/etc/xray/bootstrap-firewall.nft
  NFT_UNIT=/etc/systemd/system/xray-bootstrap-firewall.service
  NGINX_FILE=/etc/nginx/conf.d/xray-camouflage.conf
  F2B_FILE=/etc/fail2ban/jail.d/xray-bootstrap.local
  APT_FILE=/etc/apt/apt.conf.d/52xray-bootstrap-upgrades
  UPDATE_UNIT=/etc/systemd/system/xray-update.service
  UPDATE_TIMER=/etc/systemd/system/xray-update.timer
  LOCK=/run/lock/xray-bootstrap.lock
  TX_ACTIVE=false
  WORK=''
  CHILD_PID=''
  CLIENT_TEST_DIR=''
  HOST_PENDING=false
  FIREWALL_APPLIED=false
  MANAGED_FILES=("$BIN" "$UNIT" "$NFT_FILE" "$NFT_UNIT" "$NGINX_FILE" "$F2B_FILE" "$APT_FILE" "$UPDATE_UNIT" "$UPDATE_TIMER" "$SSH_DROPIN")
}
log() {
  printf '%s\n' "$*" >&2
  if [[ -n ${OPLOG:-} ]]; then printf '%s %s: %s\n' "$(date -u +%FT%TZ)" "$MODE" "$*" >>"$OPLOG"; fi
}
die() {
  log "ERROR: $*"
  exit 1
}
# A single policy for standalone preflight and install (including parser bootstrap).
supported_os() {
  case "$1:$2" in
    debian:12 | debian:13 | ubuntu:22.04 | ubuntu:24.04 | ubuntu:26.04) return 0 ;;
    *) return 1 ;;
  esac
}
check_platform() {
  local id version arch failure=false
  id=$(sed -n 's/^ID=//p' /etc/os-release | tr -d '"')
  version=$(sed -n 's/^VERSION_ID=//p' /etc/os-release | tr -d '"')
  if supported_os "$id" "$version"; then
    printf '[PASS] OS: %s %s\n' "$id" "$version"
  else
    log "[FAIL] Unsupported operating system: ${id:-unknown} ${version:-unknown}. Supported: Debian 12, 13; Ubuntu 22.04, 24.04, 26.04 (apt + systemd)."
    failure=true
  fi
  arch=$(uname -m)
  if arch_asset >/dev/null; then printf '[PASS] Architecture: %s\n' "$arch"; else failure=true; fi
  if [[ $(cat /proc/1/comm) == systemd ]] && command -v systemctl >/dev/null; then
    printf '[PASS] systemd available\n'
  else
    log '[FAIL] systemd must be PID 1 and systemctl must be installed; use a systemd VPS/VM.'
    failure=true
  fi
  if [[ $(id -u) == 0 ]]; then printf '[PASS] Root privileges\n'; else
    log '[FAIL] Root privileges required to validate listener ownership; run with sudo.'
    failure=true
  fi
  [[ $failure == false ]]
}
ipv6_available() { [[ -e /proc/net/if_inet6 ]]; }
require_tools() {
  local c
  for c in "$@"; do
    command -v "$c" >/dev/null || die "Missing dependency: $c. Install prerequisites listed in README."
  done
}
require_root() {
  [[ $EUID == 0 ]] || die 'Run mutations with sudo.'
}
lock_operation() {
  require_root
  if [[ ! -e $LOCK && ! -L $LOCK ]]; then
    (
      set -o noclobber
      : >"$LOCK"
    ) || die 'Cannot safely create the operation lock.'
  fi
  [[ -f $LOCK && ! -L $LOCK && $(stat -c %u "$LOCK") == "$EUID" && $(stat -c %h "$LOCK") == 1 ]] || die 'Unsafe operation lock ownership/type.'
  chmod 600 "$LOCK"
  exec 9>>"$LOCK"
  if [[ $MODE == recover && -n ${TRANSACTION_ID:-} ]]; then
    flock -w 300 9 || die 'Timed recovery could not obtain the operation lock; use the VPS console.'
  else
    flock -n 9 || die 'Another operation is running. Retry after it finishes.'
  fi
  install -d -m 700 "$JOURNAL"
  OPLOG=$JOURNAL/operations.log
  [[ ! -L $OPLOG ]] || die 'Unsafe operation log symlink.'
  touch "$OPLOG"
  chmod 600 "$OPLOG"
}
workspace() {
  [[ -n $WORK ]] && return 0
  WORK=$(mktemp -d) || return $?
  chmod 700 "$WORK"
}
cleanup() {
  local rc=$?
  trap - EXIT ERR INT TERM HUP
  if [[ $TX_ACTIVE == true ]]; then
    log 'Operation failed; restoring the previous deployment.'
    if ! recover_transaction; then
      log 'ERROR: recovery failed; use the VPS console and run recover.'
      rc=1
    fi
  fi
  if [[ -n $CHILD_PID ]] && kill -0 "$CHILD_PID" 2>/dev/null; then
    kill "$CHILD_PID"
    wait "$CHILD_PID" 2>/dev/null || : # SIGTERM exit is expected for the temporary client.
  fi
  if [[ -n $CLIENT_TEST_DIR && -d $CLIENT_TEST_DIR ]]; then rm -rf -- "$CLIENT_TEST_DIR"; fi
  if [[ -n $WORK && -d $WORK ]]; then rm -rf -- "$WORK"; fi
  exit "$rc"
}
setup_traps() {
  trap cleanup EXIT
  # Never print BASH_COMMAND: it may contain keys or UUIDs.
  trap 'report_error "$?" "$LINENO" "${FUNCNAME[0]:-main}"' ERR
  trap 'exit 130' INT TERM HUP
}
report_error() {
  local rc=$1 line=$2 operation=$3
  log "ERROR: $MODE: $operation failed at line $line (exit $rc)."
  if [[ $TX_ACTIVE == true ]]; then log 'Deployment transaction is active; cleanup will restore the previous deployment.'; fi
  # ERR retains the original command status. Returning nonzero from the trap
  # itself can interrupt Bash's stack unwinding before EXIT recovery runs.
  return 0
}
atomic_file() {
  local src=$1 dest=$2 mode=${3:-600} tmp
  [[ ! -L $dest ]] || die "Refusing symlink at managed file: $dest"
  tmp=$(mktemp "${dest}.tmp.XXXXXX") || return 1
  install -m "$mode" "$src" "$tmp" || return 1
  sync -f "$tmp" || return 1
  mv -fT -- "$tmp" "$dest" || return 1
}
atomic_managed_file() {
  if [[ -f $2 ]] && ! grep -q 'Managed by xray-reality-bootstrap v2' "$2"; then
    die "Existing administrator/legacy file requires review before replacement: $2"
  fi
  atomic_file "$@"
}

point_current() {
  local generation=$1 temp=$XRAY_DIR/.current-next
  [[ $generation =~ ^[0-9]{8}T[0-9]{6}-[a-f0-9]{12}$ ]] || die 'Invalid generation identifier.'
  if [[ -e $temp || -L $temp ]]; then rm -f -- "$temp" || return 1; fi
  ln -s "deployments/$generation" "$temp" || return 1
  mv -fT -- "$temp" "$CURRENT" || return 1
  sync -f "$XRAY_DIR" || return 1
}

new_id() { printf '%s-%s' "$(date -u +%Y%m%dT%H%M%S)" "$(openssl rand -hex 6)"; }
opt() { jq -er --arg k "$1" '.options[$k]' "$DESIRED"; }
# jq -e treats empty strings as success, but false/null as failures.
profile_opt() { jq -r --arg k "$1" '.[$k]' "$PROFILE"; }
retry() {
  local n=0 rc=0
  while ((n < 3)); do
    if "$@"; then return 0; else rc=$?; fi
    n=$((n + 1))
    ((n == 3)) || sleep 2
  done
  return "$rc"
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
load_deployment() {
  workspace || return $?
  DESIRED=$WORK/state.json
  if [[ -f $STATE_FILE ]]; then
    data state "$STATE_FILE" >"$DESIRED" || return $?
  elif [[ -f $XRAY_DIR/bootstrap-state.env && -f $XRAY_DIR/config.json ]]; then
    data migrate "$XRAY_DIR/bootstrap-state.env" "$XRAY_DIR/config.json" >"$DESIRED" || return $?
    log 'Legacy deployment loaded without executing shell state. Host hardening defaults are now opt-in.'
    log 'Legacy firewall and primary SSH changes require manual review; they cannot safely be attributed or undone.'
  else
    die 'No saved deployment. Install first, or restore a backup.'
  fi
}
load_profile() {
  workspace || return $?
  PROFILE=$WORK/options.json
  local legacy=false
  if [[ ! -f $STATE_FILE && -f $XRAY_DIR/bootstrap-state.env && -f $XRAY_DIR/config.json ]]; then legacy=true; fi
  if [[ -n $PROFILE_PATH ]]; then
    if [[ $legacy == true ]]; then
      data profile-legacy "$PROFILE_PATH" "$XRAY_DIR/bootstrap-state.env" "$XRAY_DIR/config.json" >"$WORK/profile-loaded" || return $?
    elif [[ -f $STATE_FILE ]]; then
      data profile-deployed "$PROFILE_PATH" "$STATE_FILE" >"$WORK/profile-loaded" || return $?
    else data profile "$PROFILE_PATH" >"$WORK/profile-loaded" || return $?; fi
  elif [[ -f $STATE_FILE ]]; then
    jq '.options' "$STATE_FILE" >"$WORK/profile-loaded" || return $?
  elif [[ $legacy == true ]]; then
    data migrate "$XRAY_DIR/bootstrap-state.env" "$XRAY_DIR/config.json" >"$WORK/legacy-profile-state" || return $?
    jq '.options' "$WORK/legacy-profile-state" >"$WORK/profile-loaded" || return $?
  elif [[ -f $XRAY_DIR/bootstrap-options.json && ! -L $XRAY_DIR/bootstrap-options.json ]]; then
    data profile "$XRAY_DIR/bootstrap-options.json" >"$WORK/profile-loaded" || return $?
  else
    data defaults >"$WORK/profile-loaded" || return $?
  fi
  data profile "$WORK/profile-loaded" >"$WORK/profile-validated" || return $?
  mv "$WORK/profile-validated" "$WORK/profile-loaded" || return $?
  mv "$WORK/profile-loaded" "$PROFILE" || return $?
  if [[ -n $PIN ]]; then
    jq --arg pin "$PIN" '.XRAY_PIN=$pin' "$PROFILE" >"$WORK/profile-next" || return $?
    data profile "$WORK/profile-next" >"$PROFILE" || return $?
  fi
  if [[ ${ALLOW_PRERELEASE_CLI:-false} == true ]]; then
    set_profile ALLOW_PRERELEASE yes || return $?
  fi
  if [[ -n $SID_COUNT ]]; then
    jq --arg count "$SID_COUNT" '.SHORT_ID_COUNT=$count' "$PROFILE" >"$WORK/profile-next" || return $?
    data profile "$WORK/profile-next" >"$PROFILE" || return $?
  fi
}

set_profile() {
  jq --arg key "$1" --arg value "$2" '.[$key]=$value' "$PROFILE" >"$WORK/profile-next" || return $?
  mv "$WORK/profile-next" "$PROFILE"
}
prompt_value() {
  local answer
  read -r -p "$1 [$2]: " answer || die 'Installation cancelled (EOF).'
  printf '%s' "${answer:-$2}"
}
wizard() {
  [[ -t 0 && $NON_INTERACTIVE == false ]] || die 'Use install --auto --non-interactive with a profile on noninteractive hosts.'
  local k value
  log 'Host firewall, SSH and OS policies are unchanged by default. Edit a profile for optional host hardening.'
  for k in SERVER_NAME DEST_ENDPOINT LISTEN_PORT FALLBACK_PORT PUBLIC_IP PROFILE_NAME FIREWALL_STYLE XRAY_UPDATE_POLICY BLOCK_PRIVATE_OUTBOUND CAMOUFLAGE_ENABLED; do
    value=$(prompt_value "$k" "$(profile_opt "$k")")
    set_profile "$k" "$value"
  done
  data profile "$PROFILE" >"$WORK/validated"
  mv "$WORK/validated" "$PROFILE"
}
make_identity() {
  local key_output private public count
  key_output=$("$CANDIDATE/xray" x25519)
  private=$(printf '%s\n' "$key_output" | sed -nE 's/^Private[Kk]ey: *([A-Za-z0-9_-]{43})$/\1/p')
  public=$(printf '%s\n' "$key_output" | sed -nE 's/^(Public[Kk]ey|Password( \(PublicKey\))?): *([A-Za-z0-9_-]{43})$/\3/p')
  [[ -n $private && -n $public ]] || die 'Unrecognized x25519 output; candidate release unsupported.'
  count=$(profile_opt SHORT_ID_COUNT)
  python3 - "$count" >"$WORK/shortids" <<'PY'
import json, secrets, sys
print(json.dumps([secrets.token_hex(8) for _ in range(int(sys.argv[1]))]))
PY
  # Secrets travel through protected files, not command-line jq arguments.
  printf '%s' "$private" >"$WORK/private"
  printf '%s' "$public" >"$WORK/public"
  cat /proc/sys/kernel/random/uuid >"$WORK/uuid"
  jq -n --slurpfile options "$PROFILE" --slurpfile ids "$WORK/shortids" \
    --rawfile private "$WORK/private" --rawfile public "$WORK/public" --rawfile id "$WORK/uuid" \
    --arg version "$CANDIDATE_VERSION" '{format:2, options:$options[0], identity:{private_key:$private,public_key:$public},
      clients:[{name:$options[0].PROFILE_NAME,id:($id|rtrimstr("\n")),short_id:$ids[0][0]}],short_ids:$ids[0],rotation:null,xray_version:$version}' >"$DESIRED"
}
validate_keypair() {
  local public expected
  # Read the private key through a root-only PKCS#8 file, never through argv.
  data key-der "$DESIRED" "$WORK/private.der"
  openssl pkey -inform DER -in "$WORK/private.der" -pubout -outform DER -out "$WORK/public.der"
  public=$(data public-key "$WORK/public.der")
  expected=$(jq -r '.identity.public_key' "$DESIRED")
  [[ -n $public && $public == "$expected" ]] || die 'REALITY public/private key mismatch.'
}

stage_generation() {
  data state "$DESIRED" >"$WORK/validated-state"
  mv "$WORK/validated-state" "$DESIRED"
  validate_keypair
  GENERATION=$(new_id)
  STAGE=$DEPLOYMENTS/$GENERATION
  install -d -m 750 -g xray-bootstrap "$XRAY_DIR" "$DEPLOYMENTS" "$STAGE"
  install -m 755 "$CANDIDATE/xray" "$STAGE/xray"
  local asset
  for asset in geoip.dat geosite.dat; do
    if [[ -f $CANDIDATE/$asset ]]; then install -m 644 "$CANDIDATE/$asset" "$STAGE/$asset"; fi
  done
  install -m 600 "$DESIRED" "$STAGE/state.json"
  data config "$DESIRED" >"$WORK/config.json"
  install -m 640 -g xray-bootstrap "$WORK/config.json" "$STAGE/config.json"
  jq '.options' "$DESIRED" >"$STAGE/options.json"
  chmod 600 "$STAGE/options.json"
  validate_xray "$STAGE/xray" "$STAGE/config.json" "$STAGE"
  # Last check runs as the service identity, catching permissions and asset failures.
  if ! runuser -u xray-bootstrap -- env XRAY_LOCATION_ASSET="$STAGE" "$STAGE/xray" run -test -config "$STAGE/config.json" >"$WORK/config-test.log" 2>&1; then
    die 'Xray service account cannot validate staged config. Check generation directory permissions privately.'
  fi
  sync -f "$STAGE"
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
begin_transaction() {
  validate_runtime_ownership
  [[ ! -d $JOURNAL/pending ]] || die 'An interrupted/pending operation exists. Run recover or confirm-host first.'
  install -d -m 700 "$JOURNAL" "$JOURNAL/pending" "$JOURNAL/pending/files"
  TX_ACTIVE=true
  local old='' f auxiliary index=0
  if [[ -L $CURRENT ]]; then
    old=$(readlink "$CURRENT")
    [[ $old =~ ^deployments/[0-9]{8}T[0-9]{6}-[a-f0-9]{12}$ ]] || die 'Unsafe current deployment symlink.'
  fi
  printf '%s\n' "$old" >"$JOURNAL/pending/previous"
  printf '%s\n' "$(new_id)" >"$JOURNAL/pending/token"
  if systemctl is-active --quiet xray; then touch "$JOURNAL/pending/was-active"; fi
  if systemctl is-enabled --quiet xray 2>/dev/null; then touch "$JOURNAL/pending/was-enabled"; fi
  for auxiliary in xray-update.timer xray-bootstrap-firewall.service; do
    if systemctl is-active --quiet "$auxiliary"; then touch "$JOURNAL/pending/$auxiliary.active"; fi
    if systemctl is-enabled --quiet "$auxiliary" 2>/dev/null; then touch "$JOURNAL/pending/$auxiliary.enabled"; fi
  done
  touch "$JOURNAL/pending/aux-state-recorded"
  for f in "${MANAGED_FILES[@]}"; do
    [[ ! -L $f ]] || die "Managed path is a symlink: $f"
    printf '%s\n' "$f" >"$JOURNAL/pending/files/$index.path"
    if [[ -f $f ]]; then cp -a -- "$f" "$JOURNAL/pending/files/$index.data"; fi
    index=$((index + 1))
  done
  if command -v nft >/dev/null && nft list table inet xray_bootstrap >"$JOURNAL/pending/nft.previous" 2>/dev/null; then
    grep -q 'comment "xray-reality-bootstrap managed"' "$JOURNAL/pending/nft.previous" || die 'Reserved nftables table exists without installer ownership; refusing takeover.'
    touch "$JOURNAL/pending/had-nft"
  fi
  ufw_owned_ports >"$JOURNAL/pending/ufw.previous"
  touch "$JOURNAL/pending/ready"
  sync -f "$JOURNAL"
}
arm_rollback() {
  local token
  token=$(cat "$JOURNAL/pending/token")
  persist_helper
  printf '%s\n' "${SSH_CONNECTION:-}" >"$JOURNAL/pending/origin-ssh"
  systemd-run --quiet --collect --unit="xray-bootstrap-rollback-$token" --on-active=180s \
    "$HELPER" recover --transaction-id "$token"
  touch "$JOURNAL/pending/armed"
}
cancel_rollback() {
  if [[ -f $JOURNAL/pending/armed ]]; then
    local timer
    timer="xray-bootstrap-rollback-$(cat "$JOURNAL/pending/token").timer"
    # An elapsed transient timer may already have been collected by systemd.
    if [[ $(systemctl show -p LoadState --value "$timer") != not-found ]]; then systemctl stop "$timer"; fi
  fi
}
stop_managed_unit() {
  local unit=$1 file=$2
  if [[ -f $file ]] && grep -q 'Managed by xray-reality-bootstrap v2' "$file"; then
    systemctl stop "$unit" || return 1
    systemctl disable "$unit" >/dev/null || return 1
  fi
  return 0
}
restore_auxiliary() {
  local unit=$1 file=$2
  [[ -f $file ]] || return 0
  if [[ ! -f $JOURNAL/pending/aux-state-recorded || -f $JOURNAL/pending/$unit.enabled ]]; then
    systemctl enable "$unit" >/dev/null || return 1
  elif systemctl is-enabled --quiet "$unit" 2>/dev/null; then systemctl disable "$unit" || return 1; fi
  if [[ ! -f $JOURNAL/pending/aux-state-recorded || -f $JOURNAL/pending/$unit.active ]]; then
    systemctl start "$unit" || return 1
  elif systemctl is-active --quiet "$unit"; then systemctl stop "$unit" || return 1; fi
  return 0
}
recover_transaction() {
  [[ -d $JOURNAL/pending ]] || return 0
  workspace || return 1
  local old f index=0
  TX_ACTIVE=false
  if [[ ! -f $JOURNAL/pending/ready ]]; then
    mv "$JOURNAL/pending" "$JOURNAL/incomplete-$(new_id)" || return 1
    log 'Incomplete journal archived; no activation occurred.'
    return 0
  fi
  old=$(cat "$JOURNAL/pending/previous") || return 1
  if [[ -n $old ]]; then
    [[ $old =~ ^deployments/[0-9]{8}T[0-9]{6}-[a-f0-9]{12}$ && -d $XRAY_DIR/$old ]] || return 1
    point_current "${old#deployments/}" || return 1
  else
    [[ ! -L $CURRENT ]] || rm -f -- "$CURRENT" || return 1
  fi
  # Disable while unit files still exist: doing so after deleting them can
  # leave enabled dangling symlinks and active transient policy behind.
  # UNIT is a shared global initialized by common.sh.
  # shellcheck disable=SC2153
  stop_managed_unit xray "$UNIT" || return 1
  if [[ -f $JOURNAL/pending/firewall-changed ]]; then stop_managed_unit xray-bootstrap-firewall.service "$NFT_UNIT" || return 1; fi
  if [[ -f $JOURNAL/pending/timer-changed ]]; then stop_managed_unit xray-update.timer "$UPDATE_TIMER" || return 1; fi
  for f in "${MANAGED_FILES[@]}"; do
    [[ $(cat "$JOURNAL/pending/files/$index.path") == "$f" ]] || return 1
    [[ ! -L $f ]] || return 1
    if [[ -f $JOURNAL/pending/files/$index.data ]]; then
      atomic_file "$JOURNAL/pending/files/$index.data" "$f" "$(stat -c %a "$JOURNAL/pending/files/$index.data")" || return 1
    elif [[ -f $f ]]; then rm -f -- "$f" || return 1; fi
    index=$((index + 1))
  done
  if [[ -f $JOURNAL/pending/firewall-changed ]]; then restore_firewall || return 1; fi
  systemctl daemon-reload || return 1
  if [[ -f $JOURNAL/pending/firewall-changed ]]; then restore_auxiliary xray-bootstrap-firewall.service "$NFT_UNIT" || return 1; fi
  if [[ -f $JOURNAL/pending/timer-changed ]]; then restore_auxiliary xray-update.timer "$UPDATE_TIMER" || return 1; fi
  if [[ -f $JOURNAL/pending/was-enabled ]]; then
    systemctl enable xray >/dev/null || return 1
  elif systemctl is-enabled --quiet xray 2>/dev/null; then
    systemctl disable xray >/dev/null || return 1
  fi
  if [[ -f $JOURNAL/pending/was-active ]]; then
    systemctl reset-failed xray || return 1
    systemctl restart xray || return 1
    if [[ -L $CURRENT ]]; then service_health || return 1; else systemctl is-active --quiet xray || return 1; fi
  else
    if systemctl is-active --quiet xray; then systemctl stop xray || return 1; fi
  fi
  if [[ -f $JOURNAL/pending/ssh-changed && ! -f $JOURNAL/pending/ssh-not-reloaded ]]; then
    sshd -t || return 1
    systemctl reload ssh || return 1
    local restored_ports
    restored_ports=$(sshd -T | awk '$1=="port" {print $2}') || return 1
    wait_ssh_listeners "$restored_ports" || return 1
  fi
  if [[ -f $JOURNAL/pending/nginx-changed ]] && command -v nginx >/dev/null; then
    nginx -t || return 1
    if systemctl is-active --quiet nginx; then systemctl reload nginx || return 1; fi
  fi
  if [[ -f $JOURNAL/pending/f2b-changed ]] && systemctl is-active --quiet fail2ban; then
    wait_fail2ban || return 1
    fail2ban-client reload || return 1
  fi
  cancel_rollback || return 1
  mv "$JOURNAL/pending" "$JOURNAL/recovered-$(new_id)" || return 1
  log 'ROLLED_BACK: previous deployment and managed files restored.'
}
commit_transaction() {
  cancel_rollback
  TX_ACTIVE=false
  mv "$JOURNAL/pending" "$JOURNAL/committed-$(new_id)"
  log 'SUCCEEDED: deployment committed.'
}
activate_generation() {
  validate_runtime_ownership
  begin_transaction
  write_service
  point_current "$GENERATION"
  systemd_action daemon-reload
  # Enforce the requested kernel boundary before a reconfigured process runs.
  # Client edits/updates retain the already deployed firewall policy.
  case "$MODE" in
    install | repair | restore)
      if [[ $(opt OS_PRIVATE_OUTBOUND) == yes ]]; then apply_firewall; fi
      ;;
  esac
  case "$MODE" in
    install | repair | restore | test) systemd_action enable xray >/dev/null ;;
  esac
  if [[ -f $JOURNAL/pending/was-active || $MODE == install || $MODE == repair || $MODE == restore || $MODE == test ]]; then
    systemd_action reset-failed xray
    systemd_action restart xray
    service_health || die 'Xray startup/listener health check failed: service must be active with its own configured TCP listeners. Inspect systemctl status xray and journalctl -u xray.'
  else
    log 'Service was inactive and remains inactive. Configuration/version validated; runtime health requires a manual start.'
  fi
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
arch_asset() {
  case "$(uname -m)" in
    x86_64 | amd64) printf '%s' Xray-linux-64.zip ;;
    aarch64 | arm64) printf '%s' Xray-linux-arm64-v8a.zip ;;
    armv7l) printf '%s' Xray-linux-arm32-v7a.zip ;;
    *)
      log "[FAIL] Unsupported architecture: $(uname -m). Supported: x86_64/amd64, aarch64/arm64, armv7l."
      return 1
      ;;
  esac
}
download() {
  local rc
  [[ $1 == https://* ]] || die 'Downloads require HTTPS.'
  if retry curl --proto '=https' --proto-redir '=https' -fLSs --connect-timeout 15 --max-time 180 "$1" -o "$2"; then return 0; else rc=$?; fi
  log "ERROR: Download failed: HTTPS GET $1 (curl exit $rc; see curl error above)."
  return "$rc"
}
validate_xray() {
  local binary=$1 config=$2 assets=$3
  jq -e 'type=="object"' "$config" >/dev/null
  if ! XRAY_LOCATION_ASSET="$assets" "$binary" run -test -format json -config "$config" >"$WORK/config-test.log" 2>&1; then
    die 'Xray rejected configuration. Active deployment is preserved; inspect the configuration privately.'
  fi
}
prepare_candidate() {
  workspace
  local asset tag url digest dgst api requested available
  requested=${PIN:-$(profile_opt XRAY_PIN)}
  api=$requested
  asset=$(arch_asset)
  if [[ -d $XRAY_DIR ]]; then
    available=$(df -Pk "$XRAY_DIR" | awk 'NR==2 {print $4}')
  else
    available=$(df -Pk / | awk 'NR==2 {print $4}')
  fi
  [[ $available =~ ^[0-9]+$ && $available -ge 524288 ]] || die 'At least 512 MiB free space is required to stage an update.'
  if [[ -n $api ]]; then
    [[ $api =~ ^v[0-9]{1,3}\.[0-9]{1,2}\.[0-9]{1,2}$ ]] || die 'Invalid --xray-version release tag.'
    api="https://api.github.com/repos/XTLS/Xray-core/releases/tags/$api"
  else api=https://api.github.com/repos/XTLS/Xray-core/releases/latest; fi
  download "$api" "$WORK/release.json"
  tag=$(jq -er '.tag_name | select(test("^v[0-9]{1,3}\\.[0-9]{1,2}\\.[0-9]{1,2}$"))' "$WORK/release.json")
  jq -e '.draft==false and (.prerelease|type=="boolean") and (.assets|type=="array")' "$WORK/release.json" >/dev/null || die 'Release metadata is invalid or draft.'
  if [[ $(jq -r '.prerelease' "$WORK/release.json") == true && ${ALLOW_PRERELEASE_CLI:-false} != true && $(profile_opt ALLOW_PRERELEASE) != yes ]]; then
    die 'Pinned release is marked prerelease upstream. Review release notes and explicitly opt in with --allow-prerelease.'
  fi
  [[ -z $requested || $tag == "$requested" ]] || die 'Release tag mismatch.'
  jq --arg asset "$asset" '[.assets[] | select(.name==$asset)] | if length==1 then .[0] else error("asset missing or duplicate") end' "$WORK/release.json" >"$WORK/asset.json"
  url=$(jq -er '.browser_download_url' "$WORK/asset.json")
  [[ $url == "https://github.com/XTLS/Xray-core/releases/download/$tag/$asset" ]] || die 'Unexpected release asset URL.'
  digest=$(jq -r '.digest // ""' "$WORK/asset.json")
  if [[ ! $digest =~ ^sha256:[a-fA-F0-9]{64}$ ]]; then
    dgst=$(jq -er --arg name "$asset.dgst" '[.assets[] | select(.name==$name)] | select(length==1) | .[0].browser_download_url' "$WORK/release.json")
    [[ $dgst == "$url.dgst" ]] || die 'Unexpected checksum URL.'
    download "$dgst" "$WORK/release.dgst"
    digest=$(sed -nE 's/^[[:space:]]*(SHA2-256|SHA256)[[:space:]]*=[[:space:]]*([a-fA-F0-9]{64})[[:space:]]*$/sha256:\2/p' "$WORK/release.dgst")
  fi
  [[ $digest =~ ^sha256:[a-fA-F0-9]{64}$ ]] || die 'No unambiguous SHA-256 checksum; refusing release.'
  digest=${digest,,}
  CANDIDATE_VERSION=$tag
  if [[ $MODE == update && -f $STATE_FILE && -z $PIN && -z $(profile_opt XRAY_PIN) ]] && jq -e --arg tag "$tag" '(.xray_version|ltrimstr("v")|split(".")|map(tonumber)) > ($tag|ltrimstr("v")|split(".")|map(tonumber))' "$STATE_FILE" >/dev/null; then
    log 'SKIPPED: upstream stable release is older than the installed version. Pin explicitly to downgrade.'
    UPDATE_SKIPPED=true
    return 0
  fi
  if [[ $MODE == update && -f $STATE_FILE && $(jq -r '.xray_version' "$STATE_FILE") == "$tag" && (-z $PIN || $(jq -r '.options.XRAY_PIN' "$STATE_FILE") == "$PIN") ]]; then
    log "SKIPPED: Xray $tag is already deployed."
    UPDATE_SKIPPED=true
    return 0
  fi
  download "$url" "$WORK/release.zip"
  [[ $(stat -c %s "$WORK/release.zip") == "$(jq -r '.size' "$WORK/asset.json")" ]] || die 'Release asset size mismatch.'
  [[ $(sha256sum "$WORK/release.zip" | cut -d' ' -f1) == "${digest#sha256:}" ]] || die 'Release SHA-256 checksum mismatch.'
  CANDIDATE=$WORK/candidate
  data extract "$WORK/release.zip" "$CANDIDATE"
  [[ -f $CANDIDATE/xray && ! -L $CANDIDATE/xray ]] || die 'Release is missing the executable.'
  chmod 755 "$CANDIDATE/xray"
  "$CANDIDATE/xray" version >"$WORK/version"
  [[ $(head -n 1 "$WORK/version") == "Xray ${tag#v} "* ]] || die 'Candidate execution/version verification failed.'
  if [[ -f $CONFIG_FILE ]]; then validate_xray "$CANDIDATE/xray" "$CONFIG_FILE" "$CANDIDATE"; fi
}
reuse_candidate() {
  if [[ -L $CURRENT ]]; then CANDIDATE=$(readlink -f "$CURRENT"); else CANDIDATE=$WORK/candidate; fi
  if [[ ! -L $CURRENT ]]; then
    install -d -m 700 "$CANDIDATE"
    install -m 755 "$BIN" "$CANDIDATE/xray"
    local f
    for f in geoip.dat geosite.dat; do
      if [[ -f /usr/local/share/xray/$f ]]; then cp /usr/local/share/xray/"$f" "$CANDIDATE/$f"; fi
    done
  fi
  CANDIDATE_VERSION=$(jq -r '.xray_version' "$DESIRED")
}
update_mode() {
  [[ -f $UNIT ]] || die 'Xray runtime is not installed. Run install, repair or restore first.'
  load_deployment
  jq '.options' "$DESIRED" >"$WORK/options.json"
  PROFILE=$WORK/options.json
  UPDATE_SKIPPED=false
  prepare_candidate
  [[ $UPDATE_SKIPPED == false ]] || return 0
  # Scheduled no-change checks must not accumulate full binary backups. Take
  # the recovery snapshot only after staging succeeds, before any deployment edit.
  backup_mode >/dev/null
  jq --arg version "$CANDIDATE_VERSION" --arg pin "$PIN" \
    '.xray_version=$version | if $pin!="" then .options.XRAY_PIN=$pin else . end' "$DESIRED" >"$WORK/next"
  mv "$WORK/next" "$DESIRED"
  if [[ ${ALLOW_PRERELEASE_CLI:-false} == true ]]; then
    jq '.options.ALLOW_PRERELEASE="yes"' "$DESIRED" >"$WORK/next"
    mv "$WORK/next" "$DESIRED"
  fi
  ensure_account
  stage_generation
  persist_helper
  activate_generation
  configure_timer
  commit_transaction
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
systemd_action() {
  local rc
  if systemctl "$@"; then return 0; else rc=$?; fi
  log "ERROR: systemd activation failed: systemctl $* (exit $rc). Inspect systemctl status xray and journalctl -u xray on the VPS."
  return "$rc"
}
validate_runtime_ownership() {
  if [[ -f $UNIT ]] && ! grep -q 'Managed by xray-reality-bootstrap v2' "$UNIT"; then
    if [[ -f $STATE_FILE || ! -f $XRAY_DIR/bootstrap-state.env ]]; then
      die 'Xray unit is not installer-owned. Review administrator changes before managing this runtime.'
    fi
    # A validated legacy deployment is explicitly migrated by repair/install.
  fi
}
ensure_account() {
  if ! getent passwd xray-bootstrap >/dev/null; then
    useradd --system --user-group --home-dir /nonexistent --no-create-home --shell /usr/sbin/nologin xray-bootstrap
  fi
  local record
  record=$(getent passwd xray-bootstrap)
  [[ $(cut -d: -f3 <<<"$record") != 0 && $(cut -d: -f6 <<<"$record") == /nonexistent && $(cut -d: -f7 <<<"$record") == /usr/sbin/nologin ]] || die 'Service account conflicts with existing account.'
  [[ $(id -G xray-bootstrap) == "$(id -g xray-bootstrap)" && $(id -gn xray-bootstrap) == xray-bootstrap ]] || die 'Service account has unexpected group privileges.'
  [[ -z $(getent group xray-bootstrap | cut -d: -f4) ]] || die 'Service group has additional members; refusing to expose configuration secrets.'
  # Root owns the directory so a compromised service cannot swap log paths
  # between the symlink check and root's ownership/permission updates.
  install -d -m 750 -o root -g xray-bootstrap /var/log/xray
  local f
  for f in error.log access.log; do
    [[ ! -L /var/log/xray/$f ]] || die 'Unsafe log symlink.'
    touch /var/log/xray/"$f"
    chown xray-bootstrap:xray-bootstrap /var/log/xray/"$f"
    chmod 600 /var/log/xray/"$f"
  done
}
write_service() {
  local firewall_dependency=''
  if [[ $(opt FIREWALL_STYLE) == nftables && -f $NFT_UNIT ]]; then
    firewall_dependency='Requires=xray-bootstrap-firewall.service'
  fi
  cat >"$WORK/xray.service" <<EOF
# Managed by xray-reality-bootstrap v2
[Unit]
Description=Xray VLESS REALITY XTLS Vision
After=network-online.target nss-lookup.target xray-bootstrap-firewall.service
Wants=network-online.target
$firewall_dependency

[Service]
Type=simple
User=xray-bootstrap
Group=xray-bootstrap
ExecStart=$CURRENT/xray run -config $CONFIG_FILE
Environment=XRAY_LOCATION_ASSET=$CURRENT
Restart=on-failure
RestartSec=3
LimitNOFILE=65536
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectControlGroups=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectKernelLogs=true
LockPersonality=true
MemoryDenyWriteExecute=true
RestrictSUIDSGID=true
RestrictRealtime=true
RestrictNamespaces=true
SystemCallArchitectures=native
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
ReadWritePaths=/var/log/xray
InaccessiblePaths=-$JOURNAL -$BACKUPS
CapabilityBoundingSet=CAP_NET_BIND_SERVICE
AmbientCapabilities=CAP_NET_BIND_SERVICE

[Install]
WantedBy=multi-user.target
EOF
  atomic_file "$WORK/xray.service" "$UNIT" 644
  cat >"$WORK/xray-wrapper" <<EOF
#!/usr/bin/env bash
# Managed by xray-reality-bootstrap v2
exec $CURRENT/xray "\$@"
EOF
  atomic_file "$WORK/xray-wrapper" "$BIN" 755
}
persist_helper() {
  local source_file
  source_file=$(readlink -f "$ENTRY_PATH")
  if [[ $source_file == "$HELPER" ]]; then return 0; fi
  # Source installs use the reproducible standalone artifact at repository root.
  if [[ $STANDALONE == false ]]; then source_file=$PROJECT_DIR/xray_reality_bootstrap.sh; fi
  [[ -r $source_file ]] || die 'Standalone helper is missing. Run scripts/build.sh.'
  atomic_file "$source_file" "$HELPER" 700
}
configure_timer() {
  local policy file legacy=false
  policy=$(opt XRAY_UPDATE_POLICY)
  if [[ -f $XRAY_DIR/bootstrap-state.env && -f $UPDATE_UNIT ]] && grep -Fxq "ExecStart=$HELPER update --non-interactive" "$UPDATE_UNIT"; then legacy=true; fi
  for file in "$UPDATE_UNIT" "$UPDATE_TIMER"; do
    if [[ -f $file && $legacy == false ]] && ! grep -q 'Managed by xray-reality-bootstrap v2' "$file"; then
      die "Unrecognized update policy file requires administrator review: $file"
    fi
  done
  touch "$JOURNAL/pending/timer-changed"
  if [[ $policy == manual ]]; then
    if systemctl is-enabled --quiet xray-update.timer 2>/dev/null; then systemctl disable --now xray-update.timer; fi
    rm -f -- "$UPDATE_UNIT" "$UPDATE_TIMER"
    return 0
  fi
  persist_helper
  cat >"$WORK/update.service" <<EOF
# Managed by xray-reality-bootstrap v2
[Unit]
Description=Transactional Xray update
After=network-online.target
Wants=network-online.target
[Service]
Type=oneshot
ExecStart=$HELPER update --non-interactive
UMask=0077
EOF
  cat >"$WORK/update.timer" <<EOF
# Managed by xray-reality-bootstrap v2
[Unit]
Description=Scheduled Xray update
[Timer]
OnCalendar=$policy
RandomizedDelaySec=30m
Persistent=true
[Install]
WantedBy=timers.target
EOF
  atomic_file "$WORK/update.service" "$UPDATE_UNIT" 644
  atomic_file "$WORK/update.timer" "$UPDATE_TIMER" 644
  systemctl daemon-reload
  systemctl enable --now xray-update.timer
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
probe_reality() {
  local target sni host rc
  target=$(profile_opt DEST_ENDPOINT)
  sni=$(profile_opt SERVER_NAME)
  require_tools openssl timeout getent
  host=${target%:*}
  host=${host#[}
  host=${host%]}
  if getent ahosts "$host" >"$WORK/dns-probe" 2>&1; then :; else
    rc=$?
    log "[FAIL] DNS resolution failed: getent ahosts $host for REALITY endpoint $target (exit $rc). Check the hostname and resolver configuration."
    return "$rc"
  fi
  # Explicit version/group/ALPN, trusted certificate and matching SNI.
  if timeout 20 openssl s_client -connect "$target" -servername "$sni" \
    -tls1_3 -groups X25519 -alpn h2 -verify_hostname "$sni" -verify_return_error \
    </dev/null >"$WORK/tls-probe" 2>&1; then :; else
    rc=$?
    log "[FAIL] REALITY TLS negotiation failed: endpoint=$target SNI=$sni; openssl s_client TLS 1.3/X25519/h2 certificate verification (exit $rc)."
    # OpenSSL output contains public peer data, never deployment credentials.
    tail -n 20 "$WORK/tls-probe" >&2
    [[ $rc != 124 ]] || log 'TLS probe timed out after 20 seconds; check endpoint reachability and outbound access.'
    return "$rc"
  fi
  if ! grep -Eq 'TLSv1.3|TLS 1.3' "$WORK/tls-probe"; then
    log "[FAIL] REALITY endpoint=$target SNI=$sni did not negotiate TLS 1.3. Choose a TLS 1.3 target."
    return 1
  fi
  if ! grep -q 'ALPN protocol: h2' "$WORK/tls-probe"; then
    log "[FAIL] REALITY endpoint=$target SNI=$sni did not negotiate HTTP/2 (h2). Choose an h2-capable target."
    return 1
  fi
  log 'REALITY target negotiated verified TLS 1.3 with X25519 and h2. This does not guarantee camouflage on every network.'
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
ufw_owned_ports() {
  if ! command -v ufw >/dev/null; then return 0; fi
  LC_ALL=C ufw status numbered 2>/dev/null | sed -nE 's/.*# xray-bootstrap-([0-9]+)[[:space:]]*$/\1/p' | sort -nu
}
ufw_remove_owned() {
  local numbers n
  numbers=$(LC_ALL=C ufw status numbered | sed -nE 's/^\[[[:space:]]*([0-9]+)\].*# xray-bootstrap-[0-9]+[[:space:]]*$/\1/p' | sort -rn)
  while read -r n; do
    [[ -z $n ]] || ufw --force delete "$n" || return 1
  done <<<"$numbers"
}
firewall_conflicts() {
  local style
  style=$(opt FIREWALL_STYLE)
  [[ $style == none ]] && return 0
  if systemctl is-active --quiet firewalld; then die 'firewalld is active; use FIREWALL_STYLE=none and manage ports there.'; fi
  if [[ $style == nftables ]] && command -v ufw >/dev/null && LC_ALL=C ufw status | grep '^Status: active' >/dev/null; then
    die 'UFW is active. Select ufw or none; the installer will not disable it.'
  fi
  if [[ $style == ufw ]]; then
    LC_ALL=C ufw status | grep '^Status: active' >/dev/null || die 'UFW must already be active. Enable/configure it separately while preserving SSH.'
    if [[ $(opt LISTEN_ADDRESS) == *:* ]] && ! grep -Eq '^IPV6=yes$' /etc/default/ufw; then
      die 'UFW IPv6 is disabled; enable it separately or select IPv4 LISTEN_ADDRESS.'
    fi
  fi
}
render_nft() {
  local ports uid v4 v6
  ports=$(opt LISTEN_PORT)
  [[ -z $(opt FALLBACK_PORT) ]] || ports+=", $(opt FALLBACK_PORT)"
  printf 'table inet xray_bootstrap {\n  comment "xray-reality-bootstrap managed"\n'
  printf '  chain input { type filter hook input priority -10; policy accept;\n'
  printf '    tcp dport { %s } counter accept comment "xray-bootstrap ports"\n  }\n' "$ports"
  if [[ $(opt OS_PRIVATE_OUTBOUND) == yes ]]; then
    uid=$(id -u xray-bootstrap)
    v4=$(data cidrs 4 | jq -r 'join(", ")')
    v6=$(data cidrs 6 | jq -r 'join(", ")')
    printf '  chain output { type filter hook output priority 10; policy accept;\n'
    printf '    ct direction reply meta skuid %s accept\n' "$uid"
    printf '    meta skuid %s ip daddr { %s } counter reject\n' "$uid" "$v4"
    printf '    meta skuid %s ip6 daddr { %s } counter reject\n  }\n' "$uid" "$v6"
  fi
  printf '}\n'
}
nft_apply_file() {
  local file=$1
  if nft list table inet xray_bootstrap >"$WORK/nft-current" 2>/dev/null; then
    if ! grep -q 'comment "xray-reality-bootstrap managed"' "$WORK/nft-current"; then
      log 'ERROR: reserved nftables table is not installer-owned; refusing replacement.'
      return 1
    fi
    printf 'delete table inet xray_bootstrap\n' >"$WORK/nft-batch"
  else : >"$WORK/nft-batch"; fi
  cat "$file" >>"$WORK/nft-batch" || return 1
  nft -c -f "$WORK/nft-batch" || return 1
  nft -f "$WORK/nft-batch" || return 1
}
apply_firewall() {
  [[ $FIREWALL_APPLIED == false ]] || return 0
  local style port file
  style=$(opt FIREWALL_STYLE)
  [[ $style == none ]] && return 0
  if [[ $style == nftables ]]; then
    for file in "$NFT_FILE" "$NFT_UNIT"; do
      if [[ -f $file ]] && ! grep -q 'Managed by xray-reality-bootstrap v2' "$file"; then die "Unrecognized firewall file requires administrator review: $file"; fi
    done
  fi
  firewall_conflicts
  jq '.options' "$DESIRED" >"$WORK/egress-options"
  data egress-check "$WORK/egress-options" /etc/resolv.conf
  # Arm a watchdog before changing any live networking state.
  arm_rollback
  touch "$JOURNAL/pending/firewall-changed"
  if [[ $style == nftables ]]; then
    render_nft >"$WORK/firewall.nft"
    nft_apply_file "$WORK/firewall.nft"
    {
      printf '# Managed by xray-reality-bootstrap v2\n'
      printf 'add table inet xray_bootstrap\ndelete table inet xray_bootstrap\n'
      cat "$WORK/firewall.nft"
    } >"$WORK/firewall-persistent.nft"
    nft -c -f "$WORK/firewall-persistent.nft"
    atomic_managed_file "$WORK/firewall-persistent.nft" "$NFT_FILE" 600
    cat >"$WORK/firewall.service" <<EOF
# Managed by xray-reality-bootstrap v2
[Unit]
Description=Installer-owned Xray firewall table
After=network-pre.target ufw.service nftables.service
Before=xray.service
[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/sbin/nft -f $NFT_FILE
[Install]
WantedBy=multi-user.target
EOF
    atomic_managed_file "$WORK/firewall.service" "$NFT_UNIT" 644
    systemctl daemon-reload
    systemctl enable --now xray-bootstrap-firewall.service >/dev/null
    write_service
    systemctl daemon-reload
  else
    for port in "$(opt LISTEN_PORT)" "$(opt FALLBACK_PORT)"; do
      [[ -n $port ]] || continue
      # Adding a duplicate rule can update its comment in UFW. Preserve
      # existing administrator rules instead of claiming their ownership.
      if LC_ALL=C ufw status numbered | grep -E "^[[] *[0-9]+[]] +${port}/tcp( +| +\(v6\))" | grep -v '# xray-bootstrap-' | grep . >/dev/null; then
        log "Port $port already has an administrator UFW rule; leaving it unchanged."
        continue
      fi
      ufw --dry-run allow "$port/tcp" comment "xray-bootstrap-$port" >/dev/null
      ufw allow "$port/tcp" comment "xray-bootstrap-$port"
    done
  fi
  log 'Firewall additions are pending. Existing host drop rules may still block Xray.'
  log 'Within 180 seconds, verify connectivity and run confirm-host in a new SSH session; otherwise changes roll back.'
  HOST_PENDING=true
  FIREWALL_APPLIED=true
}
restore_firewall() {
  local port
  if command -v nft >/dev/null; then
    if [[ -f $JOURNAL/pending/had-nft ]]; then
      nft_apply_file "$JOURNAL/pending/nft.previous" || return 1
    elif nft list table inet xray_bootstrap >/dev/null 2>&1; then nft delete table inet xray_bootstrap || return 1; fi
  fi
  if command -v ufw >/dev/null; then
    ufw_remove_owned || return 1
    while read -r port; do
      [[ -z $port ]] || ufw allow "$port/tcp" comment "xray-bootstrap-$port" || return 1
    done <"$JOURNAL/pending/ufw.previous"
  fi
}
remove_firewall() {
  if [[ -f $NFT_FILE ]]; then
    grep -q 'Managed by xray-reality-bootstrap v2' "$NFT_FILE" || die 'Persisted firewall file is not installer-owned; refusing removal.'
    if [[ -f $NFT_UNIT ]]; then
      grep -q 'Managed by xray-reality-bootstrap v2' "$NFT_UNIT" || die 'Firewall unit is not installer-owned; refusing removal.'
    fi
    if nft list table inet xray_bootstrap >/dev/null 2>&1; then nft delete table inet xray_bootstrap; fi
    if systemctl is-enabled --quiet xray-bootstrap-firewall.service 2>/dev/null; then systemctl disable --now xray-bootstrap-firewall.service; fi
    rm -f -- "$NFT_FILE" "$NFT_UNIT"
  fi
  if command -v ufw >/dev/null; then ufw_remove_owned; fi
}

clear_firewall_mode() {
  load_deployment
  reuse_candidate
  jq '.options.FIREWALL_STYLE="none" | .options.OS_PRIVATE_OUTBOUND="no"' "$DESIRED" >"$WORK/next"
  mv "$WORK/next" "$DESIRED"
  stage_generation
  activate_generation
  arm_rollback
  touch "$JOURNAL/pending/firewall-changed"
  remove_firewall
  TX_ACTIVE=false
  log 'Installer firewall rules removed provisionally. Confirm-host from a fresh SSH session within 180 seconds.'
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
wait_ssh_listeners() {
  local attempt p main_pid ready
  [[ -n $1 ]] || return 1
  for ((attempt = 0; attempt < 30; attempt++)); do
    main_pid=$(systemctl show -p MainPID --value ssh) || return 1
    if [[ $main_pid =~ ^[1-9][0-9]*$ ]]; then
      ready=true
      while read -r p; do
        [[ -n $p ]] || continue
        [[ $p =~ ^[0-9]{1,5}$ ]] || return 1
        if ! ss -H -lntp "sport = :$p" | grep "pid=$main_pid," >/dev/null; then ready=false; fi
      done <<<"$1"
      [[ $ready != true ]] || return 0
    fi
    sleep 1
  done
  return 1
}
ssh_check_port() {
  local ports=$1 current_port=${SSH_CONNECTION:-}
  current_port=${current_port##* }
  if [[ $(opt CHANGE_SSH_PORT) == yes ]]; then
    opt SSH_PORT
  elif [[ -n ${SSH_CONNECTION:-} ]] && grep -qx "$current_port" <<<"$ports"; then
    printf '%s\n' "$current_port"
  else
    head -n1 <<<"$ports"
  fi
}
harden_ssh_mode() {
  load_deployment
  if [[ -n $PROFILE_PATH ]]; then
    load_profile
    jq --slurpfile options "$PROFILE" '.options += ($options[0] | {SSH_HARDENING,SSH_PORT,CHANGE_SSH_PORT,DISABLE_PASSWORD_AUTH,HAS_SSH_KEYS})' "$DESIRED" >"$WORK/next"
    mv "$WORK/next" "$DESIRED"
  fi
  [[ $(opt SSH_HARDENING) == yes ]] || die 'Set SSH_HARDENING=yes in your profile for this separate operation.'
  require_tools sshd ss
  [[ -d /etc/ssh/sshd_config.d ]] || die 'sshd drop-ins are unavailable. Configure SSH manually.'
  grep -Eiq '^[[:space:]]*Include[[:space:]]+/etc/ssh/sshd_config.d/\*.conf' /etc/ssh/sshd_config || die 'Primary sshd_config does not include drop-ins; configure it manually.'
  if systemctl is-active --quiet ssh.socket; then die 'SSH socket activation is active. Migrate ports manually or disable socket activation through the VPS console.'; fi
  if [[ $(opt DISABLE_PASSWORD_AUTH) == yes && $KEY_CONFIRMED != true ]]; then
    die 'Password disabling requires --key-login-confirmed after testing a fresh key login. HAS_SSH_KEYS alone is insufficient.'
  fi
  sshd -t
  sshd -T >"$WORK/ssh-before"
  local ports new_port p
  ports=$(awk '$1=="port" {print $2}' "$WORK/ssh-before")
  [[ -n $ports ]] || die 'Cannot determine effective SSH ports.'
  new_port=$(ssh_check_port "$ports")
  if [[ $(opt CHANGE_SSH_PORT) != yes ]]; then
    jq --arg port "$new_port" '.options.SSH_PORT=$port' "$DESIRED" >"$WORK/next"
    mv "$WORK/next" "$DESIRED"
  fi
  begin_transaction
  arm_rollback
  touch "$JOURNAL/pending/ssh-not-reloaded" "$JOURNAL/pending/ssh-changed"
  {
    printf '# Managed by xray-reality-bootstrap v2; original ports retained\n'
    while read -r p; do printf 'Port %s\n' "$p"; done <<<"$ports"
    if [[ $(opt CHANGE_SSH_PORT) == yes ]] && ! grep -qx "$new_port" <<<"$ports"; then printf 'Port %s\n' "$new_port"; fi
    printf 'PubkeyAuthentication yes\n'
    if [[ $(opt DISABLE_PASSWORD_AUTH) == yes ]]; then
      printf 'PasswordAuthentication no\nKbdInteractiveAuthentication no\n'
    fi
  } >"$WORK/ssh-dropin"
  atomic_managed_file "$WORK/ssh-dropin" "$SSH_DROPIN" 600
  sshd -t
  local remote local_address local_port
  read -r remote _ local_address local_port <<<"${SSH_CONNECTION:-127.0.0.1 0 127.0.0.1 22}"
  sshd -T -C "user=${SUDO_USER:-root},addr=$remote,host=$remote,laddr=$local_address,lport=$new_port" >"$WORK/ssh-after"
  grep -qx 'pubkeyauthentication yes' "$WORK/ssh-after" || die 'Administrator precedence prevents requested PubkeyAuthentication; rolling back.'
  if [[ $(opt DISABLE_PASSWORD_AUTH) == yes ]]; then
    grep -qx 'passwordauthentication no' "$WORK/ssh-after" || die 'PasswordAuthentication did not take effect; rolling back.'
    grep -qx 'kbdinteractiveauthentication no' "$WORK/ssh-after" || die 'KbdInteractiveAuthentication did not take effect; rolling back.'
  fi
  if [[ $(opt CHANGE_SSH_PORT) == yes ]]; then
    grep -qx "port $new_port" "$WORK/ssh-after" || die 'New SSH port did not take effect.'
    log 'Open the new SSH port in your existing host/cloud firewall before proceeding. Original SSH ports remain enabled.'
  fi
  rm -f -- "$JOURNAL/pending/ssh-not-reloaded"
  systemctl reload ssh
  configure_fail2ban
  local expected_ports=$ports
  if [[ $(opt CHANGE_SSH_PORT) == yes ]]; then
    expected_ports+=$'\n'"$new_port"
  fi
  wait_ssh_listeners "$expected_ports" || die 'Required SSH listeners did not become ready; rolling back.'
  # SSH settings are not proxy settings: persist requested posture only after SSH confirmation.
  install -m 600 "$DESIRED" "$JOURNAL/pending/ssh-state.json"
  if [[ $(opt CHANGE_SSH_PORT) == yes ]]; then
    printf '%s\n' "$new_port" >"$JOURNAL/pending/ssh-port"
  else
    printf '%s\n' "$ports" >"$JOURNAL/pending/ssh-port"
  fi
  [[ $(opt DISABLE_PASSWORD_AUTH) != yes ]] || touch "$JOURNAL/pending/key-confirmation-required"
  log 'SSH change is pending for 180 seconds. Test a fresh login, then run confirm-host --key-login-confirmed if using keys.'
  TX_ACTIVE=false
}
confirm_host_mode() {
  [[ -d $JOURNAL/pending && -f $JOURNAL/pending/armed ]] || die 'No pending host transition.'
  [[ -n ${SSH_CONNECTION:-} ]] || die 'Confirm from a fresh SSH session after external connectivity testing.'
  [[ ! -f $JOURNAL/pending/origin-ssh || ${SSH_CONNECTION:-} != "$(cat "$JOURNAL/pending/origin-ssh")" ]] || die 'Use a fresh SSH session, not the session that applied the change.'
  if [[ -f $JOURNAL/pending/ssh-changed ]]; then
    grep -qx "${SSH_CONNECTION##* }" "$JOURNAL/pending/ssh-port" || die 'Confirmation must come from the requested SSH port.'
    if [[ -f $JOURNAL/pending/key-confirmation-required && $KEY_CONFIRMED != true ]]; then die 'Confirm the fresh login used a key with --key-login-confirmed.'; fi
  fi
  TX_ACTIVE=true
  if [[ -f $JOURNAL/pending/ssh-changed ]]; then
    if [[ -f $JOURNAL/pending/ssh-state.json ]]; then
      load_deployment
      cp "$JOURNAL/pending/ssh-state.json" "$DESIRED"
      reuse_candidate
      stage_generation
      point_current "$GENERATION"
      if [[ -f $JOURNAL/pending/was-active ]]; then
        systemctl reset-failed xray
        systemctl restart xray
      fi
    fi
  fi
  if [[ -f $JOURNAL/pending/was-active ]]; then service_health || die 'Xray health failed; restoring the previous deployment.'; fi
  commit_transaction
}
restore_ssh_mode() {
  load_deployment
  [[ -f $SSH_DROPIN ]] || die 'No installer SSH drop-in to remove.'
  grep -q 'Managed by xray-reality-bootstrap v2' "$SSH_DROPIN" || die 'Drop-in is not installer-owned.'
  begin_transaction
  arm_rollback
  touch "$JOURNAL/pending/ssh-not-reloaded" "$JOURNAL/pending/ssh-changed"
  rm -f -- "$SSH_DROPIN"
  sshd -t
  sshd -T >"$WORK/ssh-restored"
  awk '$1=="port" {print $2}' "$WORK/ssh-restored" >"$JOURNAL/pending/ssh-port"
  rm -f -- "$JOURNAL/pending/ssh-not-reloaded"
  systemctl reload ssh
  configure_fail2ban
  jq --arg port "$(head -n1 "$JOURNAL/pending/ssh-port")" '.options.SSH_HARDENING="no" | .options.CHANGE_SSH_PORT="no" | .options.DISABLE_PASSWORD_AUTH="no" | .options.SSH_PORT=$port' "$DESIRED" >"$JOURNAL/pending/ssh-state.json"
  wait_ssh_listeners "$(cat "$JOURNAL/pending/ssh-port")" || die 'Restored SSH listeners did not become ready.'
  log 'Administrator SSH settings restored provisionally. Confirm from a fresh session on a restored port within 180 seconds.'
  TX_ACTIVE=false
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
apt_action() {
  local rc
  if retry env DEBIAN_FRONTEND=noninteractive apt-get "$@"; then return 0; else rc=$?; fi
  log "ERROR: Package operation failed: apt-get $* (exit $rc); check repository, network and package errors above."
  return "$rc"
}
install_dependencies() {
  local packages=(ca-certificates curl openssl jq python3 iproute2 util-linux)
  local missing=() package
  [[ $(opt FIREWALL_STYLE) != nftables ]] || packages+=(nftables)
  [[ $(opt FIREWALL_STYLE) != ufw ]] || packages+=(ufw)
  [[ $(opt CAMOUFLAGE_ENABLED) != yes ]] || packages+=(nginx)
  # The managed journal jail needs python3-systemd/nft. Distribution defaults
  # may also enable a file-backed sshd jail, which needs the local syslog daemon.
  [[ $(opt FAIL2BAN_ENABLED) != yes ]] || packages+=(fail2ban python3-systemd nftables rsyslog logrotate)
  [[ $(opt UNATTENDED_UPGRADES_ENABLED) != yes ]] || packages+=(unattended-upgrades)
  for package in "${packages[@]}"; do
    if [[ $(dpkg-query -W -f='${Status}' "$package" 2>/dev/null) != 'install ok installed' ]]; then
      missing+=("$package")
    fi
  done
  if ((${#missing[@]} == 0)); then
    log 'Dependencies already installed; retaining existing package versions.'
    return 0
  fi
  apt_action update
  apt_action install -y --no-remove --no-install-recommends "${missing[@]}"
}
configure_host_extras() {
  if [[ $(opt CAMOUFLAGE_ENABLED) == yes ]]; then
    touch "$JOURNAL/pending/nginx-changed"
    # Loopback diagnostics site, deliberately unrelated to REALITY TLS forwarding.
    cat >"$WORK/nginx.conf" <<EOF
# Managed by xray-reality-bootstrap v2
server {
    listen 127.0.0.1:$(opt CAMOUFLAGE_WEB_PORT);
    server_name _;
    location = /healthz { default_type text/plain; return 200 "ok\n"; }
    location / { default_type text/html; return 200 "<h1>Service gateway</h1>"; }
}
EOF
    atomic_managed_file "$WORK/nginx.conf" "$NGINX_FILE" 644
    nginx -t
    systemctl enable --now nginx
    systemctl reload nginx
    [[ $(curl -fsS --max-time 5 "http://127.0.0.1:$(opt CAMOUFLAGE_WEB_PORT)/healthz") == ok ]] || die 'Managed Nginx health endpoint did not return the expected response.'
  elif [[ -f $NGINX_FILE ]] && grep -q 'Managed by xray-reality-bootstrap v2' "$NGINX_FILE"; then
    touch "$JOURNAL/pending/nginx-changed"
    rm -f -- "$NGINX_FILE"
    nginx -t
    if systemctl is-active --quiet nginx; then systemctl reload nginx; fi
  fi
  configure_fail2ban
  if [[ $(opt UNATTENDED_UPGRADES_ENABLED) == yes ]]; then
    [[ ! -f /etc/apt/apt.conf.d/20auto-upgrades ]] || die 'Administrator unattended-upgrades policy exists. Leave installer option disabled and manage it directly.'
    cat >"$WORK/apt-policy" <<'EOF'
// Managed by xray-reality-bootstrap v2
APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";
EOF
    atomic_managed_file "$WORK/apt-policy" "$APT_FILE" 644
  elif [[ -f $APT_FILE ]] && grep -q 'Managed by xray-reality-bootstrap v2' "$APT_FILE"; then
    rm -f -- "$APT_FILE"
  fi
}

wait_fail2ban() {
  local attempts=0
  while ((attempts < 30)); do
    if fail2ban-client ping >/dev/null 2>&1; then return 0; fi
    attempts=$((attempts + 1))
    sleep 1
  done
  return 1
}
configure_fail2ban() {
  if [[ $(opt FAIL2BAN_ENABLED) == yes ]]; then
    # Existing administrator sshd jail remains unchanged. Never disable fail2ban.
    touch "$JOURNAL/pending/f2b-changed"
    local ssh_ports
    ssh_ports=$(opt SSH_PORT)
    if command -v sshd >/dev/null; then
      ssh_ports=$(sshd -T | awk '$1=="port" {ports=ports sep $2; sep=","} END{print ports}')
    fi
    [[ $ssh_ports =~ ^[0-9]{1,5}(,[0-9]{1,5})*$ ]] || die 'Cannot determine SSH ports for fail2ban.'
    cat >"$WORK/fail2ban" <<EOF
# Managed by xray-reality-bootstrap v2
[xray-bootstrap-sshd]
enabled = true
filter = sshd
backend = systemd
banaction = nftables-multiport
port = $ssh_ports
maxretry = 5
findtime = 10m
bantime = 1h
EOF
    atomic_managed_file "$WORK/fail2ban" "$F2B_FILE" 644
    if ! fail2ban-client -t >"$WORK/fail2ban-test" 2>&1; then
      atomic_file "$WORK/fail2ban-test" "$JOURNAL/fail2ban-validation.log" 600
      die "Fail2ban configuration is invalid. Inspect $JOURNAL/fail2ban-validation.log privately and resolve administrator jail backend/log paths."
    fi
    systemctl enable --now fail2ban
    touch "$JOURNAL/pending/f2b-changed"
    wait_fail2ban || die 'Fail2ban control socket did not become ready. Inspect its service journal privately.'
    fail2ban-client reload
    fail2ban-client status xray-bootstrap-sshd >"$WORK/fail2ban-status" 2>&1
  elif [[ -f $F2B_FILE ]] && grep -q 'Managed by xray-reality-bootstrap v2' "$F2B_FILE"; then
    touch "$JOURNAL/pending/f2b-changed"
    rm -f -- "$F2B_FILE"
    if systemctl is-active --quiet fail2ban; then
      wait_fail2ban || die 'Fail2ban is active but its control socket is unavailable.'
      fail2ban-client reload
    fi
  fi
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
backup_mode() {
  local backup id f n=0
  id=$(new_id)
  backup=$BACKUPS/$id
  install -d -m 700 "$BACKUPS" "$backup" "$backup/managed"
  if [[ -L $CURRENT ]]; then
    cp -a --dereference "$CURRENT" "$backup/deployment"
  else
    load_deployment
    install -d -m 700 "$backup/deployment"
    install -m 600 "$DESIRED" "$backup/deployment/state.json"
    install -m 600 "$XRAY_DIR/config.json" "$backup/deployment/config.json"
    install -m 755 "$BIN" "$backup/deployment/xray"
  fi
  for f in "${MANAGED_FILES[@]}"; do
    if [[ -f $f && ! -L $f ]]; then
      cp -a -- "$f" "$backup/managed/$n.data"
      printf '%s\n' "$f" >"$backup/managed/$n.path"
    fi
    n=$((n + 1))
  done
  printf '2\n' >"$backup/format"
  # Manifest generated with relative paths; restoration never executes manifests.
  # shellcheck disable=SC2094
  (cd "$backup" && find . -type f ! -name SHA256SUMS -print0 | sort -z | xargs -0 sha256sum >SHA256SUMS)
  chmod -R go-rwx "$backup"
  sync -f "$backup"
  printf '%s\n' "$id"
}
validate_backup() {
  local backup=$1
  [[ -d $backup && ! -L $backup ]] || die 'Unsupported backup.'
  # Restrict contents before checking hashes, disallow links, special files and unmanifested data.
  python3 - "$backup" <<'PY'
import hashlib, os, pathlib, re, sys
root = pathlib.Path(sys.argv[1])
paths = list(root.rglob('*'))
for path in [root, *paths]:
    if path.is_symlink() or not (path.is_file() or path.is_dir()):
        sys.exit('Unsafe backup file')
    info = path.stat()
    if info.st_uid != os.geteuid() or info.st_mode & 0o022:
        sys.exit('Backup must be owned by the restoring user and not writable by other users')
if not (root / 'format').is_file() or (root / 'format').stat().st_size != 2 or (root / 'format').read_bytes() != b'2\n':
    sys.exit('Unsupported backup format')
if (root / 'SHA256SUMS').stat().st_size > 1024 * 1024:
    sys.exit('Oversized backup manifest')
expected = {}
for line in (root / 'SHA256SUMS').read_text().splitlines():
    m = re.fullmatch(r'([0-9a-f]{64})  (\./[A-Za-z0-9._/-]+)', line)
    if not m or '..' in m[2].split('/') or m[2] in expected:
        sys.exit('Invalid backup manifest')
    expected[m[2]] = m[1]
actual = set()
for path in paths:
    if path.is_file() and path != root / 'SHA256SUMS':
        relative = './' + str(path.relative_to(root))
        actual.add(relative)
        digest = hashlib.sha256()
        with path.open('rb') as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                digest.update(chunk)
        if expected.get(relative) != digest.hexdigest():
            sys.exit('Backup checksum mismatch')
if actual != set(expected):
    sys.exit('Backup manifest file set mismatch')
PY
  data state "$backup/deployment/state.json" >"$WORK/restore-state"
  data config "$WORK/restore-state" >"$WORK/restore-config"
  # Legacy backup configurations may include old but valid fallback fields.
  validate_xray "$backup/deployment/xray" "$WORK/restore-config" "$backup/deployment"
}
restore_mode() {
  [[ $NAME =~ ^[0-9]{8}T[0-9]{6}-[a-f0-9]{12}$ ]] || die 'restore requires a backup ID from list-backups.'
  workspace
  local backup=$BACKUPS/$NAME
  validate_backup "$backup"
  if [[ -f $STATE_FILE || -f $XRAY_DIR/bootstrap-state.env ]]; then backup_mode >/dev/null; fi
  if [[ -f $STATE_FILE ]]; then
    jq --slurpfile live "$STATE_FILE" '.options += ($live[0].options | {SSH_HARDENING,SSH_PORT,CHANGE_SSH_PORT,DISABLE_PASSWORD_AUTH,HAS_SSH_KEYS})' "$WORK/restore-state" >"$WORK/restore-next"
    mv "$WORK/restore-next" "$WORK/restore-state"
  fi
  DESIRED=$WORK/restore-state
  CANDIDATE=$backup/deployment
  CANDIDATE_VERSION=$(jq -r '.xray_version' "$DESIRED")
  ensure_account
  stage_generation
  activate_generation
  configure_host_extras
  configure_timer
  apply_firewall
  finish_install
  log 'Deployment restored. Managed proxy/host rules regenerated from saved options. Archived files are retained for private comparison. SSH settings were preserved.'
}
list_backups_mode() {
  [[ -d $BACKUPS ]] || return 0
  find "$BACKUPS" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' | sort
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
client_change_mode() {
  [[ -f $UNIT ]] || die 'Xray runtime is not installed. Run install, repair or restore first.'
  load_deployment
  data mutate "$DESIRED" "$MODE" "$NAME" "$WINDOW" >"$WORK/next"
  mv "$WORK/next" "$DESIRED"
  reuse_candidate
  stage_generation
  activate_generation
  commit_transaction
  if [[ $MODE == remove-client || $MODE == rotate-client ]]; then
    # Delete only that client's exports, never glob based on a user-controlled name.
    local prefix
    prefix=$(printf '%s' "$NAME" | sha256sum | cut -c1-24)
    if [[ -d $CLIENT_DIR ]]; then find "$CLIENT_DIR" -maxdepth 1 -type f -name "$prefix-*" -delete; fi
  fi
  if [[ $MODE == rotate-shortid ]]; then
    log "Old and new shortIds are accepted. Export updated clients; finalize-shortid after $WINDOW seconds revokes old shortIds."
  fi
  log 'Client change deployed. Existing sessions may disconnect because Xray was restarted.'
}
export_client_mode() {
  load_deployment
  [[ ! -L $CLIENT_DIR ]] || die 'Unsafe export directory symlink.'
  install -d -m 700 "$CLIENT_DIR"
  local prefix uri
  prefix=$(data export "$DESIRED" "$NAME" "$CLIENT_DIR")
  if command -v qrencode >/dev/null; then
    local label
    for label in primary fallback; do
      uri=$CLIENT_DIR/$prefix-$label.uri.txt
      if [[ -f $uri ]]; then
        qrencode -t PNG -o "$CLIENT_DIR/$prefix-$label.uri.qr.png" <"$uri"
        qrencode -t UTF8 <"$uri" >"$CLIENT_DIR/$prefix-$label.uri.qr.txt"
        chmod 600 "$CLIENT_DIR/$prefix-$label.uri.qr.png" "$CLIENT_DIR/$prefix-$label.uri.qr.txt"
      fi
    done
  fi
  log "Exports saved to $CLIENT_DIR/$prefix-* (mode 600)."
  if [[ $MODE == show-client ]]; then cat "$CLIENT_DIR/$prefix-primary.uri.txt"; fi
}
reprint_mode() {
  load_deployment
  local client
  while IFS= read -r client; do
    NAME=$client
    export_client_mode
  done < <(jq -r '.clients[].name' "$DESIRED")
}
list_clients_mode() {
  load_deployment
  jq '[.clients[] | {name,credential:"redacted"}]' "$DESIRED"
}
test_client_mode() {
  load_deployment
  [[ $TEST_URL == https://* ]] || die 'test-client requires --test-url https://HOST/PATH.'
  local prefix port config
  prefix=$(data export "$DESIRED" "$NAME" "$WORK/test-export")
  port=$(
    python3 - <<'PY'
import socket
with socket.socket() as s:
    s.bind(('127.0.0.1', 0))
    print(s.getsockname()[1])
PY
  )
  CLIENT_TEST_DIR=$(mktemp -d /run/xray-bootstrap-client.XXXXXX)
  chown root:xray-bootstrap "$CLIENT_TEST_DIR"
  chmod 750 "$CLIENT_TEST_DIR"
  config=$CLIENT_TEST_DIR/client.json
  jq --argjson port "$port" '.inbounds=[{listen:"127.0.0.1",port:$port,protocol:"socks",settings:{auth:"noauth"}}] | .log={loglevel:"none"}' \
    "$WORK/test-export/$prefix-v2rayn-primary.json" >"$WORK/client-test.json"
  install -m 640 -g xray-bootstrap "$WORK/client-test.json" "$config"
  runuser -u xray-bootstrap -- "$CURRENT/xray" run -config "$config" >"$WORK/client-test.log" 2>&1 &
  CHILD_PID=$!
  local n=0
  while ! ss -H -lnt "sport = :$port" | grep . >/dev/null; do
    kill -0 "$CHILD_PID" 2>/dev/null || die 'Temporary test client failed to start.'
    n=$((n + 1))
    ((n < 20)) || die 'Temporary client listener did not appear.'
    sleep 0.2
  done
  curl --proto '=https' --noproxy '' -fsS --max-time 20 --socks5-hostname "127.0.0.1:$port" "$TEST_URL" >/dev/null || die 'End-to-end request failed. Check PUBLIC_IP, REALITY target, server time and host/cloud firewall.'
  log 'End-to-end VLESS + REALITY + Vision request succeeded.'
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
runtime_identity() {
  [[ $1 =~ ^[1-9][0-9]*$ ]] || return 1
  python3 - "$1" "$CURRENT/xray" "$CONFIG_FILE" "$(id -u xray-bootstrap)" <<'PY'
import os, pathlib, sys
pid, executable, config, uid = sys.argv[1:]
try:
    process = pathlib.Path('/proc') / pid
    arguments = (process / 'cmdline').read_bytes().split(b'\0')[:-1]
    uids = next(line.split()[1:] for line in (process / 'status').read_text().splitlines() if line.startswith('Uid:'))
    correct = (os.path.realpath(process / 'exe') == os.path.realpath(executable)
               and arguments[1:] == [b'run', b'-config', os.fsencode(config)]
               and uids == [uid] * 4)
except (OSError, StopIteration):
    correct = False
sys.exit(0 if correct else 1)
PY
}
service_health() {
  local tries=0 p main_pid
  while ((tries < 10)); do
    if systemctl is-active --quiet xray; then
      local listening=true
      main_pid=$(systemctl show -p MainPID --value xray)
      if [[ ! $main_pid =~ ^[1-9][0-9]*$ ]] || ! runtime_identity "$main_pid"; then
        tries=$((tries + 1))
        sleep 1
        continue
      fi
      for p in "$(jq -r '.options.LISTEN_PORT' "$STATE_FILE")" "$(jq -r '.options.FALLBACK_PORT' "$STATE_FILE")"; do
        [[ -n $p ]] || continue
        if ! ss -H -lntp "sport = :$p" | grep "pid=$main_pid," >/dev/null; then listening=false; fi
      done
      if [[ $listening == true ]]; then
        sleep 1
        systemctl is-active --quiet xray && return 0
      fi
    fi
    tries=$((tries + 1))
    sleep 1
  done
  return 1
}
diagnose_mode() {
  load_deployment
  local active=false config_ok=false listeners=false identity_ok=false nginx_ok=true firewall_ok=true timer_ok=true
  if systemctl is-active --quiet xray; then active=true; fi
  if XRAY_LOCATION_ASSET="$CURRENT" "$CURRENT/xray" run -test -config "$CONFIG_FILE" >"$WORK/config-test.log" 2>&1; then config_ok=true; fi
  local p listening_count=0 port_count=0 main_pid
  main_pid=0
  if [[ $active == true ]]; then
    if ! main_pid=$(systemctl show -p MainPID --value xray); then main_pid=0; fi
    if runtime_identity "$main_pid"; then identity_ok=true; fi
  fi
  for p in "$(opt LISTEN_PORT)" "$(opt FALLBACK_PORT)"; do
    [[ -n $p ]] || continue
    port_count=$((port_count + 1))
    if [[ $main_pid =~ ^[1-9][0-9]*$ ]] && ss -H -lntp "sport = :$p" | grep "pid=$main_pid," >/dev/null; then listening_count=$((listening_count + 1)); fi
  done
  if ((listening_count == port_count)); then listeners=true; fi
  if [[ $(opt CAMOUFLAGE_ENABLED) == yes ]]; then
    if [[ $(curl -fsS --max-time 4 "http://127.0.0.1:$(opt CAMOUFLAGE_WEB_PORT)/healthz") != ok ]]; then nginx_ok=false; fi
  fi
  case "$(opt FIREWALL_STYLE)" in
    nftables)
      if ! nft list table inet xray_bootstrap >"$WORK/firewall-check" 2>/dev/null; then firewall_ok=false; else
        if ! grep -q 'comment "xray-reality-bootstrap managed"' "$WORK/firewall-check"; then firewall_ok=false; fi
        if [[ $(opt OS_PRIVATE_OUTBOUND) == yes ]] && ! grep -q 'skuid' "$WORK/firewall-check"; then firewall_ok=false; fi
      fi
      ;;
    ufw)
      if ! LC_ALL=C ufw status | grep '^Status: active' >/dev/null; then firewall_ok=false; fi
      ;;
  esac
  if [[ $(opt XRAY_UPDATE_POLICY) != manual ]] && ! systemctl is-active --quiet xray-update.timer; then timer_ok=false; fi
  jq -n --argjson service "$active" --argjson config "$config_ok" --argjson listeners "$listeners" --argjson identity "$identity_ok" \
    --argjson nginx "$nginx_ok" --argjson firewall "$firewall_ok" --argjson timer "$timer_ok" \
    --argjson pending "$([[ -d $JOURNAL/pending ]] && printf true || printf false)" \
    '{service:$service,configuration:$config,listeners:$listeners,runtime_identity:$identity,loopback_site:$nginx,managed_firewall:$firewall,update_timer:$timer,pending_transition:$pending,
      external_connectivity:"not tested",credentials:"redacted"}'
  [[ $active == true && $config_ok == true && $listeners == true && $identity_ok == true && $nginx_ok == true && $firewall_ok == true && $timer_ok == true ]]
}
preflight_mode() {
  local failure=false p service storage='' ipv6=true dependencies_missing=false listeners main_pid previous_style
  if ! check_platform; then failure=true; fi
  for p in bash jq python3 curl openssl flock ss timeout getent systemctl apt-get dpkg-query runuser useradd; do
    if ! command -v "$p" >/dev/null; then
      log "[FAIL] Missing dependency: $p. Install the prerequisites listed in README, then rerun preflight."
      dependencies_missing=true
    fi
  done
  if [[ $dependencies_missing == true ]]; then
    log 'Preflight FAILED. No deployment or host policy changes applied.'
    return 1
  fi
  printf '[PASS] Required dependencies\n'
  if ! storage=$(df -Pk / | awk 'NR==2{print $4}'); then storage=''; fi
  if [[ ! $storage =~ ^[0-9]+$ || $storage -lt 524288 ]]; then
    log "[FAIL] Free storage: ${storage:-unknown} KiB; at least 524288 KiB (512 MiB) required on /."
    failure=true
  else printf '[PASS] Free storage: %s KiB\n' "$storage"; fi
  ipv6_available || ipv6=false
  if ! workspace; then
    log '[FAIL] Cannot create a private temporary workspace; check TMPDIR permissions and free space.'
    return 1
  fi
  if ! load_profile >"$WORK/profile-check.log" 2>&1; then
    log "[FAIL] Invalid profile: $(cat "$WORK/profile-check.log")"
    log 'Preflight FAILED. No deployment or host policy changes applied.'
    return 1
  fi
  printf '[PASS] Valid profile\n'
  if [[ $(profile_opt LISTEN_ADDRESS) == *:* && $ipv6 == false ]]; then
    log '[FAIL] IPv6 unavailable for the selected listener; enable IPv6 or set LISTEN_ADDRESS to 0.0.0.0.'
    failure=true
  elif [[ $ipv6 == true ]]; then printf '[PASS] IPv6 available\n'; else printf '[PASS] IPv4 listener selected; IPv6 unavailable\n'; fi
  printf 'Plan: install/update Xray deployment, dedicated service account, helper and selected managed files.\n'
  printf 'Selected policies: firewall=%s SSH=%s OS-upgrades=%s Xray-updates=%s OS-egress=%s\n' \
    "$(profile_opt FIREWALL_STYLE)" "$(profile_opt SSH_HARDENING)" "$(profile_opt UNATTENDED_UPGRADES_ENABLED)" "$(profile_opt XRAY_UPDATE_POLICY)" "$(profile_opt OS_PRIVATE_OUTBOUND)"
  printf 'Xray listeners: address=%s primary=%s alternate=%s; REALITY target=%s SNI=%s\n' \
    "$(profile_opt LISTEN_ADDRESS)" "$(profile_opt LISTEN_PORT)" "$(profile_opt FALLBACK_PORT)" "$(profile_opt DEST_ENDPOINT)" "$(profile_opt SERVER_NAME)"
  printf 'Managed runtime paths: %s/*, %s, %s, %s\n' "$DEPLOYMENTS" "$UNIT" "$BIN" "$HELPER"
  case "$(profile_opt FIREWALL_STYLE)" in
    nftables) printf 'Firewall plan: replace only inet xray_bootstrap; persist %s and %s; timed confirmation required.\n' "$NFT_FILE" "$NFT_UNIT" ;;
    ufw) printf 'Firewall plan: add tagged TCP rules for selected proxy ports; preserve administrator rules; timed confirmation required.\n' ;;
    none) printf 'Firewall plan: leave host policies unchanged; arrange provider/host port access separately.\n' ;;
  esac
  if [[ $(profile_opt SSH_HARDENING) == yes ]]; then printf 'SSH is a separate harden-ssh operation; install does not apply this request.\n'; fi
  if [[ $(profile_opt CAMOUFLAGE_ENABLED) == yes ]]; then
    printf 'Nginx plan: managed loopback site in %s. Installing nginx may also activate distribution default sites; review first.\n' "$NGINX_FILE"
  fi
  for p in "$(profile_opt LISTEN_PORT)" "$(profile_opt FALLBACK_PORT)"; do
    [[ -n $p ]] || continue
    if ! listeners=$(ss -H -lntp "sport = :$p" 2>&1); then
      log "[FAIL] Cannot inspect TCP port $p with ss: $listeners"
      failure=true
    elif [[ -n $listeners ]]; then
      main_pid=$(systemctl show -p MainPID --value xray 2>/dev/null) || main_pid=0
      if [[ -f $STATE_FILE && $main_pid =~ ^[1-9][0-9]*$ ]] && runtime_identity "$main_pid" &&
        [[ $listeners == *"pid=$main_pid,"* ]] && ! grep -v "pid=$main_pid," <<<"$listeners" | grep . >/dev/null; then
        printf '[PASS] Port %s owned by the managed Xray deployment (PID %s)\n' "$p" "$main_pid"
      else
        failure=true
        log "[FAIL] Port $p occupied by: $listeners. Stop/reconfigure the conflicting service or choose another LISTEN_PORT."
      fi
    else printf '[PASS] Port %s available\n' "$p"; fi
  done
  if [[ $(profile_opt CAMOUFLAGE_ENABLED) == yes ]] && command -v ss >/dev/null; then
    p=$(profile_opt CAMOUFLAGE_WEB_PORT)
    if ! listeners=$(ss -H -lntp "sport = :$p" 2>&1); then
      failure=true
      log "[FAIL] Cannot inspect Nginx port $p with ss: $listeners"
    elif [[ -n $listeners ]]; then
      if [[ ! -f $NGINX_FILE ]] || ! grep -q 'Managed by xray-reality-bootstrap v2' "$NGINX_FILE" || ! grep -Fq "listen 127.0.0.1:$p;" "$NGINX_FILE"; then
        failure=true
        log "[FAIL] Local Nginx diagnostics port $p occupied by: $listeners"
      fi
    fi
  fi
  for service in xray ssh ssh.socket nginx ufw nftables firewalld fail2ban; do
    if systemctl is-active --quiet "$service" 2>/dev/null; then printf 'Existing service: %s\n' "$service"; fi
  done
  for p in "$XRAY_DIR/config.json" "$STATE_FILE" /etc/ssh/sshd_config /etc/nginx/nginx.conf /etc/nftables.conf /etc/apt/apt.conf.d/20auto-upgrades; do
    [[ ! -f $p ]] || printf 'Existing configuration: %s\n' "$p"
  done
  if [[ -f $STATE_FILE ]]; then
    previous_style=$(jq -er '.options.FIREWALL_STYLE' "$STATE_FILE") || previous_style=invalid
    if [[ $previous_style != none && $previous_style != "$(profile_opt FIREWALL_STYLE)" ]]; then
      failure=true
      log '[FAIL] Changing firewall managers requires clear-firewall and confirmation first; inspect saved state if invalid.'
    fi
  fi
  if [[ ! -f $STATE_FILE && ! -f $XRAY_DIR/bootstrap-state.env ]]; then
    if [[ -f $UNIT || -e $BIN || -L $BIN ]] || systemctl cat xray.service >/dev/null 2>&1; then
      log '[FAIL] Existing unmanaged Xray service/binary found: refusing takeover; migrate or back up the existing installation first.'
      failure=true
    fi
  fi
  if [[ $(profile_opt FIREWALL_STYLE) == nftables ]] && command -v ufw >/dev/null && LC_ALL=C ufw status | grep '^Status: active' >/dev/null; then
    failure=true
    log '[FAIL] Firewall conflict: UFW is active; select none or manage the existing firewall separately.'
  fi
  if [[ $(profile_opt FIREWALL_STYLE) != none ]] && systemctl is-active --quiet firewalld; then
    failure=true
    log '[FAIL] Firewall conflict: firewalld is active; select none and manage ports there.'
  fi
  if [[ $(profile_opt FIREWALL_STYLE) == ufw ]] && ! LC_ALL=C ufw status 2>/dev/null | grep '^Status: active' >/dev/null; then
    failure=true
    log '[FAIL] UFW must already be active; activate it separately or select none.'
  fi
  if [[ $(profile_opt UNATTENDED_UPGRADES_ENABLED) == yes && -f /etc/apt/apt.conf.d/20auto-upgrades ]]; then
    failure=true
    log '[FAIL] Existing apt periodic policy prevents installer opt-in; manage it separately.'
  fi
  if ! data egress-check "$PROFILE" /etc/resolv.conf >"$WORK/egress-check.log" 2>&1; then
    log "[FAIL] Outbound policy validation: $(cat "$WORK/egress-check.log")"
    failure=true
  fi
  if [[ $NETWORK_CHECK == true ]]; then
    if ! probe_reality; then failure=true; fi
  else printf 'Network/TLS reachability not tested; use --network-check.\n'; fi
  if [[ $failure == true ]]; then
    log 'Preflight FAILED. No deployment or host policy changes applied.'
    return 1
  fi
  printf 'Preflight PASSED. No deployment or host policy changes applied.\n'
  return 0
}
dry_run_mode() {
  log "Read-only plan for $MODE. No deployment, packages, SSH or firewall will be changed."
  case "$MODE" in
    install | preflight) preflight_mode ;;
    add-client | remove-client | rotate-client | rotate-shortid | finalize-shortid)
      load_deployment || return $?
      data mutate "$DESIRED" "$MODE" "$NAME" "$WINDOW" >"$WORK/proposed-state" || return $?
      data config "$WORK/proposed-state" >"$WORK/proposed-config" || return $?
      printf 'Plan: validate and activate the requested client change, restart Xray, retain recovery generation.\n'
      jq '[.clients[]|{name,credentials:"redacted"}]' "$WORK/proposed-state"
      ;;
    *)
      load_deployment || return $?
      if [[ $MODE == harden-ssh && -n $PROFILE_PATH ]]; then
        load_profile || return $?
        jq --slurpfile options "$PROFILE" '.options += ($options[0] | {SSH_HARDENING,SSH_PORT,CHANGE_SSH_PORT,DISABLE_PASSWORD_AUTH,HAS_SSH_KEYS})' "$DESIRED" >"$WORK/proposed-state"
        mv "$WORK/proposed-state" "$DESIRED"
      fi
      if [[ $MODE == restore ]]; then
        [[ $NAME =~ ^[0-9]{8}T[0-9]{6}-[a-f0-9]{12}$ && -d $BACKUPS/$NAME ]] || die 'Select an existing backup ID from list-backups.'
        printf 'Restore plan: read backup %s, validate checksums/config/binary, preserve live SSH policy, activate saved deployment and regenerate managed host options.\n' "$NAME"
      fi
      printf 'Plan for %s: operate on installer-owned deployment/files only. Credentials are retained unless explicitly rotated or revoked.\n' "$MODE"
      printf 'Selected firewall=%s, updates=%s, SSH request=%s. Backups and rollback journal protect deployment transitions.\n' \
        "$(opt FIREWALL_STYLE)" "$(opt XRAY_UPDATE_POLICY)" "$(opt SSH_HARDENING)"
      if [[ $MODE == harden-ssh ]]; then
        printf 'SSH plan: managed drop-in %s; requested port=%s change-port=%s password-disable=%s; keep original ports, validate effective settings, confirm from a fresh session.\n' \
          "$SSH_DROPIN" "$(opt SSH_PORT)" "$(opt CHANGE_SSH_PORT)" "$(opt DISABLE_PASSWORD_AUTH)"
      elif [[ $MODE == uninstall ]]; then
        printf 'Uninstall plan: stop installed Xray, remove owned runtime/unit/rules, retain deployment secrets, exports, backups and helper. SSH restoration must be confirmed first.\n'
      fi
      printf 'Service activation, downloaded binary compatibility, external connectivity and kernel policy activation are not tested in dry-run.\n'
      ;;
  esac
}

#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
usage() {
  cat <<'EOF'
Usage: xray_reality_bootstrap.sh COMMAND [CLIENT_NAME | BACKUP_ID] [OPTIONS]
Commands:
  install update repair preflight status diagnose reprint uninstall
  add-client remove-client list-clients show-client rotate-client export-client
  rotate-shortid finalize-shortid backup restore list-backups recover
  harden-ssh restore-ssh confirm-host firewall-sync clear-firewall test-client
Options:
  --auto --non-interactive --profile-json PATH --dry-run --network-check --allow-prerelease
  --xray-version vN.N.N --shortid-count 1..16 --migration-window SECONDS
  --key-login-confirmed --yes --json --transaction-id TOKEN --test-url HTTPS_URL
Install defaults: no firewall/SSH/OS changes, manual Xray updates, private routing block.
Use preflight first. Firewall and SSH transitions require confirm-host in a new
SSH session within 180 seconds. Credentials are printed only by show-client.
EOF
}
parse_args() {
  ALLOW_PRERELEASE_CLI=false
  MODE=install AUTO=false NON_INTERACTIVE=false DRY_RUN=false PROFILE_PATH='' PIN='' SID_COUNT=''
  NAME='' WINDOW=604800 KEY_CONFIRMED=false YES=false NETWORK_CHECK=false TRANSACTION_ID='' TEST_URL=''
  local positional=false
  if (($#)) && [[ $1 != -* ]]; then
    MODE=$1
    shift
  fi
  case "$MODE" in
    install | update | repair | preflight | status | diagnose | reprint | uninstall | add-client | remove-client | list-clients | show-client | rotate-client | export-client | rotate-shortid | finalize-shortid | backup | restore | list-backups | recover | harden-ssh | restore-ssh | confirm-host | firewall-sync | clear-firewall | test-client) ;;
    *) die 'Unknown command. Use --help.' ;;
  esac
  while (($#)); do
    case "$1" in
      --profile-json=* | --xray-version=* | --shortid-count=* | --migration-window=* | --transaction-id=* | --test-url=*)
        set -- "${1%%=*}" "${1#*=}" "${@:2}"
        ;;
    esac
    case "$1" in
      --auto) AUTO=true ;;
      --allow-prerelease) ALLOW_PRERELEASE_CLI=true ;;
      --non-interactive) NON_INTERACTIVE=true ;;
      --dry-run) DRY_RUN=true ;;
      --network-check) NETWORK_CHECK=true ;;
      --key-login-confirmed) KEY_CONFIRMED=true ;;
      --yes) YES=true ;;
      --json) : ;; # Status/diagnose are always structured and redacted.
      --profile-json | --xray-version | --shortid-count | --migration-window | --transaction-id | --test-url)
        (($# >= 2)) || die "Missing value for $1"
        case "$1" in
          --profile-json) PROFILE_PATH=$2 ;;
          --xray-version) PIN=$2 ;;
          --shortid-count) SID_COUNT=$2 ;;
          --migration-window) WINDOW=$2 ;;
          --transaction-id) TRANSACTION_ID=$2 ;;
          --test-url) TEST_URL=$2 ;;
        esac
        shift
        ;;
      -h | --help)
        usage
        exit 0
        ;;
      -V | --version)
        printf 'xray-reality-bootstrap v2.0.0\n'
        exit 0
        ;;
      --)
        shift
        (($# == 1)) || die 'Expected one name after --'
        NAME=$1
        positional=true
        ;;
      -*) die "Unknown option: $1" ;;
      *)
        [[ $positional == false ]] || die 'Too many positional arguments'
        NAME=$1
        positional=true
        ;;
    esac
    shift
  done
  [[ $WINDOW =~ ^[0-9]{1,8}$ ]] || die 'Migration window must be 0-31536000 seconds.'
  WINDOW=$((10#$WINDOW))
  ((WINDOW <= 31536000)) || die 'Migration window cannot exceed one year.'
  if [[ -n $SID_COUNT ]]; then [[ $SID_COUNT =~ ^([1-9]|1[0-6])$ ]] || die 'shortid-count must be 1-16.'; fi
  if [[ -n $PIN ]]; then [[ $PIN =~ ^v[0-9]{1,3}\.[0-9]{1,2}\.[0-9]{1,2}$ ]] || die 'Invalid version tag.'; fi
  case "$MODE" in add-client | remove-client | show-client | rotate-client | export-client | restore | test-client) [[ -n $NAME ]] || die "$MODE requires a name or backup ID" ;; esac
}
install_mode() {
  workspace
  if load_profile >"$WORK/profile-check.log" 2>&1; then :; else
    log "[FAIL] Invalid profile: $(cat "$WORK/profile-check.log")"
    exit 1
  fi
  [[ $AUTO == true ]] || wizard
  # Preflight checks run before packages or service changes. Requested profile
  # is passed through to prevent checks from using different wizard defaults.
  PROFILE_PATH=$PROFILE
  # A conditional call is intentional: expected validation failures must not
  # trigger ERR/recovery. Preflight checks explicitly propagate helper errors.
  if preflight_mode; then :; else exit $?; fi
  DESIRED=$WORK/state.json
  if [[ -f $STATE_FILE || -f $XRAY_DIR/bootstrap-state.env ]]; then
    load_deployment
    backup_mode >/dev/null
    jq --slurpfile options "$PROFILE" '.options=$options[0]' "$DESIRED" >"$WORK/next"
    mv "$WORK/next" "$DESIRED"
  else
    jq -n --slurpfile options "$PROFILE" '{options:$options[0]}' >"$DESIRED"
  fi
  install_dependencies
  probe_reality
  prepare_candidate
  if ! jq -e '.identity' "$DESIRED" >/dev/null; then make_identity; else
    jq --arg version "$CANDIDATE_VERSION" '.xray_version=$version' "$DESIRED" >"$WORK/next"
    mv "$WORK/next" "$DESIRED"
  fi
  ensure_account
  stage_generation
  persist_helper
  activate_generation
  configure_host_extras
  configure_timer
  apply_firewall
  finish_install
}
finish_install() {
  if [[ $HOST_PENDING == true ]]; then
    # Leave durable journal for the separate confirmer/watchdog.
    TX_ACTIVE=false
  else commit_transaction; fi
  log 'Xray deployed. Run diagnose, then export-client NAME. No credentials were printed.'
  [[ $(opt SSH_HARDENING) != yes ]] || log 'SSH option requested: run harden-ssh separately after confirming proxy installation.'
}
repair_mode() {
  load_deployment
  backup_mode >/dev/null
  reuse_candidate
  ensure_account
  stage_generation
  persist_helper
  activate_generation
  configure_host_extras
  configure_timer
  apply_firewall
  finish_install
}
uninstall_mode() {
  [[ -f $STATE_FILE ]] || die 'Migrate legacy deployment with repair before uninstall; legacy host policies need manual review.'
  [[ ! -f $SSH_DROPIN ]] || die 'Run restore-ssh and confirm-host first to restore administrator SSH settings safely.'
  validate_runtime_ownership
  if [[ $YES != true ]]; then
    [[ -t 0 && $NON_INTERACTIVE == false ]] || die 'Uninstall requires --yes or interactive confirmation.'
    [[ $(prompt_value 'Remove managed runtime files? Type REMOVE; backups/credentials are retained' '') == REMOVE ]] || die 'Cancelled.'
  fi
  load_deployment
  backup_mode >/dev/null
  begin_transaction
  touch "$JOURNAL/pending/timer-changed" "$JOURNAL/pending/firewall-changed"
  if systemctl is-active --quiet xray; then systemctl stop xray; fi
  if systemctl is-enabled --quiet xray 2>/dev/null; then systemctl disable xray; fi
  if systemctl is-enabled --quiet xray-update.timer 2>/dev/null; then systemctl disable --now xray-update.timer; fi
  remove_firewall
  local f
  for f in "$UNIT" "$BIN" "$UPDATE_UNIT" "$UPDATE_TIMER" "$NGINX_FILE" "$F2B_FILE" "$APT_FILE"; do
    if [[ -f $f ]]; then
      if grep -q 'Managed by xray-reality-bootstrap v2' "$f"; then
        rm -f -- "$f"
      else
        log "Retained unrecognized administrator/legacy file: $f"
      fi
    fi
  done
  if command -v nginx >/dev/null && systemctl is-active --quiet nginx; then
    nginx -t
    systemctl reload nginx
  fi
  if command -v fail2ban-client >/dev/null && systemctl is-active --quiet fail2ban; then
    touch "$JOURNAL/pending/f2b-changed"
    fail2ban-client reload
  fi
  systemctl daemon-reload
  commit_transaction
  log 'Managed runtime removed. Backups, deployment credentials, exports, helper and service account retained for recovery; delete them explicitly when no longer needed.'
}
main() {
  init_paths
  parse_args "$@"
  umask 077
  setup_traps
  if [[ $MODE == install && $DRY_RUN == false && $AUTO == false ]] && [[ ! -t 0 || $NON_INTERACTIVE == true ]]; then
    die 'Noninteractive install requires --auto; no packages or host policies were changed.'
  fi
  # Reject unsupported platforms before even bootstrapping parser packages.
  if [[ $MODE == install && $DRY_RUN == false ]]; then
    if check_platform; then :; else exit 1; fi
  fi
  # Fresh VPS convenience: only real install can bootstrap parsers. Read-only
  # modes never install packages, write host policies or acquire a write lock.
  local bootstrap_packages=()
  command -v jq >/dev/null || bootstrap_packages+=(jq)
  command -v python3 >/dev/null || bootstrap_packages+=(python3)
  if [[ $MODE == install && $DRY_RUN == false ]] && ((${#bootstrap_packages[@]} > 0)); then
    [[ $EUID == 0 ]] || die 'Run install with sudo.'
    lock_operation
    apt_action update
    apt_action install -y --no-remove --no-install-recommends "${bootstrap_packages[@]}"
  fi
  if [[ $MODE == preflight || ($MODE == install && $DRY_RUN == true) ]]; then
    if dry_run_mode; then exit 0; else exit $?; fi
  fi
  require_tools jq python3 openssl
  if [[ $DRY_RUN == true ]]; then
    dry_run_mode
    return
  fi
  case "$MODE" in
    status | diagnose)
      diagnose_mode
      return
      ;;
    list-clients)
      list_clients_mode
      return
      ;;
    list-backups)
      list_backups_mode
      return
      ;;
  esac
  lock_operation
  if [[ -d $JOURNAL/pending && $MODE != recover && $MODE != confirm-host ]]; then
    die 'Pending/interrupted transition found. Run recover, or confirm-host after connectivity verification.'
  fi
  case "$MODE" in
    # Keep install outside a conditional so errexit remains active for deployment
    # mutations. Validation exits explicitly before a transaction is started.
    install) install_mode ;;
    update) update_mode ;;
    repair) repair_mode ;;
    reprint) reprint_mode ;;
    add-client | remove-client | rotate-client | rotate-shortid | finalize-shortid) client_change_mode ;;
    show-client | export-client) export_client_mode ;;
    backup) backup_mode ;;
    restore) restore_mode ;;
    harden-ssh) harden_ssh_mode ;;
    restore-ssh) restore_ssh_mode ;;
    confirm-host) confirm_host_mode ;;
    recover)
      if [[ -n $TRANSACTION_ID ]]; then
        [[ -f $JOURNAL/pending/token ]] || return 0
        [[ $(cat "$JOURNAL/pending/token") == "$TRANSACTION_ID" ]] || return 0
      fi
      recover_transaction
      ;;
    firewall-sync)
      workspace
      load_deployment
      firewall_conflicts
      [[ $(opt FIREWALL_STYLE) == nftables ]] || die 'firewall-sync requires the deployed nftables policy.'
      [[ -f $NFT_FILE ]] || die 'No persisted managed firewall table.'
      grep -q 'Managed by xray-reality-bootstrap v2' "$NFT_FILE" || die 'Persisted firewall file is not installer-owned.'
      nft_apply_file "$NFT_FILE"
      ;;
    clear-firewall) clear_firewall_mode ;;
    test-client) test_client_mode ;;
    uninstall) uninstall_mode ;;
  esac
}

if [[ ${BASH_SOURCE[0]} == "$0" ]]; then main "$@"; fi
